package com.prometheus.clq.data

import com.prometheus.clq.model.Difficulty
import com.prometheus.clq.model.Question

object QuestionsExpansion13 {
    fun get(): List<Question> = listOf(
        Question(9000, "En quelle année la Grande Muraille de Chine a-t-elle été construite?", listOf("500 avant J.C.", "200 avant J.C.", "100 après J.C.", "500 après J.C."), 1, "Histoire", Difficulty.MEDIUM, explanation = "La construction de la Grande Muraille a débuté au IIIe siècle avant J.-C. sous la dynastie Qin, vers 200 avant J.-C., pour protéger l'empire des invasions nomades."),
        Question(9001, "Qui a fondé l'Empire romain?", listOf("Julius Caesar", "Auguste", "Pompée", "Marc Antoine"), 1, "Histoire", Difficulty.EASY, explanation = "Auguste, premier empereur romain, a mis fin à la République après la guerre civile et a instauré le principat en 27 av. J.-C., fondant ainsi l'Empire romain."),
        Question(9002, "En quelle année a commencé la Révolution française?", listOf("1776", "1789", "1799", "1815"), 1, "Histoire", Difficulty.EASY, explanation = "La Révolution française débute en 1789 avec la convocation des États généraux, puis la prise de la Bastille le 14 juillet, marquant la fin de l'Ancien Régime."),
        Question(9003, "Quel pharaon égyptien a ordonné la construction de la Grande Pyramide de Giza?", listOf("Khéops", "Khéphren", "Thoutmosis", "Ramsès II"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Khéops, second pharaon de la IVe dynastie, a fait édifier la Grande Pyramide vers 2560 av. J.-C. comme tombeau royal, la plus grande des pyramides de Gizeh."),
        Question(9004, "Qui a conquis l'Égypte en 332 avant J.C.?", listOf("Darius III", "Alexandre le Grand", "Ptolémée", "Cléopâtre"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Alexandre le Grand, roi de Macédoine, a conquis l'Égypte en 332 avant J.-C., mettant fin à la domination perse et fondant la ville d'Alexandrie."),
        Question(9005, "En quelle année l'Empire romain s'est-il effondré en Occident?", listOf("410", "476", "527", "565"), 1, "Histoire", Difficulty.HARD, explanation = "En 476, le dernier empereur romain d'Occident, Romulus Augustule, fut déposé par le chef barbare Odoacre, marquant traditionnellement la fin de l'Empire romain d'Occident."),
        Question(9006, "Quel est le siège du Siège de Troie selon la mythologie?", listOf("10 mois", "5 ans", "10 ans", "15 ans"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Selon la mythologie grecque, la guerre de Troie a duré dix ans, les Grecs assiégeant la ville de Troie pour récupérer Hélène. Cette durée symbolique est un élément central du récit homérique."),
        Question(9007, "Qui était Néron?", listOf("Un général romain", "Un empereur romain", "Un gladiateur célèbre", "Un pharaon"), 1, "Histoire", Difficulty.EASY, explanation = "Néron fut le dernier empereur de la dynastie julio-claudienne, régnant sur l'Empire romain de 54 à 68 après J.-C."),
        Question(9008, "En quelle année Christophe Colomb a-t-il découvert l'Amérique?", listOf("1480", "1492", "1510", "1520"), 1, "Histoire", Difficulty.EASY, explanation = "Christophe Colomb, naviguant pour le compte de l'Espagne, atteint les Amériques le 12 octobre 1492, croyant avoir trouvé une route vers les Indes par l'ouest."),
        Question(9009, "Quel empire a construit Machu Picchu?", listOf("Aztèque", "Inca", "Maya", "Toltèque"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Machu Picchu a été construite au XVe siècle sous le règne de l'empereur inca Pachacutec, comme domaine royal ou sanctuaire religieux."),
        Question(9010, "En quelle année la Magna Carta a-t-elle été signée?", listOf("1200", "1215", "1230", "1265"), 1, "Histoire", Difficulty.HARD, explanation = "La Magna Carta a été signée en 1215 sous le règne du roi Jean d'Angleterre, à Runnymede, pour limiter les pouvoirs royaux et garantir certains droits aux barons."),
        Question(9011, "Qui a mené la Croisade des Enfants?", listOf("Baudouin IV", "Étienne de Cloyes", "Robert d'Anjou", "Louis VII"), 1, "Histoire", Difficulty.HARD, explanation = "Étienne de Cloyes, un berger français, a conduit en 1212 une croisade populaire d'enfants et de pauvres vers Jérusalem, qui s'est soldée par un échec tragique."),
        Question(9012, "Quel roi de France a participé à la croisade contre les Albigeois?", listOf("Louis VII", "Louis IX", "Philippe Auguste", "Louis VIII"), 1, "Histoire", Difficulty.HARD, explanation = "Louis IX, dit Saint Louis, mena la croisade contre les Albigeois au XIIIe siècle, dans le cadre de la lutte contre l'hérésie cathare dans le sud de la France."),
        Question(9013, "En quelle année Jeanne d'Arc a-t-elle été brûlée?", listOf("1429", "1431", "1445", "1453"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Jeanne d'Arc a été exécutée à Rouen le 30 mai 1431, après avoir été condamnée pour hérésie par un tribunal ecclésiastique pro-anglais."),
        Question(9014, "Qui a inventé l'imprimerie?", listOf("Léonard de Vinci", "Gutenberg", "Alcuin", "Charlemagne"), 1, "Histoire", Difficulty.EASY, explanation = "Johannes Gutenberg a mis au point la presse à imprimer à caractères mobiles en métal vers 1450, révolutionnant la diffusion du savoir en Europe."),
        Question(9015, "En quelle année Martin Luther a-t-il affiché ses 95 thèses?", listOf("1500", "1517", "1530", "1545"), 1, "Histoire", Difficulty.HARD, explanation = "Martin Luther aurait affiché ses 95 thèses sur la porte de l'église de Wittenberg le 31 octobre 1517, un acte considéré comme le déclencheur de la Réforme protestante."),
        Question(9016, "Quel roi d'Angleterre a rompu avec Rome?", listOf("Édouard III", "Henri VIII", "Richard III", "Jean sans Terre"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Henri VIII a rompu avec l'Église catholique romaine en 1534 par l'Acte de suprématie, principalement parce que le pape refusait d'annuler son mariage avec Catherine d'Aragon."),
        Question(9017, "En quelle année l'Armada espagnole a-t-elle attaqué l'Angleterre?", listOf("1580", "1588", "1595", "1605"), 1, "Histoire", Difficulty.HARD, explanation = "L'invincible Armada, une flotte espagnole massive, fut envoyée par Philippe II en 1588 pour envahir l'Angleterre, mais elle subit une défaite décisive face à la marine anglaise et à des tempêtes."),
        Question(9018, "Qui a découvert le détroit de Magellan?", listOf("Christophe Colomb", "Vasco de Gama", "Ferdinand de Magellan", "Bartolomeu Dias"), 2, "Histoire", Difficulty.HARD, explanation = "En 1520, Ferdinand de Magellan mena l'expédition espagnole qui traversa pour la première fois le détroit situé à la pointe sud de l'Amérique, reliant les océans Atlantique et Pacifique."),
        Question(9019, "En quelle année le Traité de Westphalie a-t-il été signé?", listOf("1640", "1648", "1660", "1672"), 1, "Histoire", Difficulty.HARD, explanation = "Le Traité de Westphalie, signé en 1648, mit fin à la guerre de Trente Ans en Europe. Il est considéré comme fondateur du système moderne d'États-nations souverains."),
        Question(9020, "Quel roi de France a construit le Château de Versailles?", listOf("Louis XIII", "Louis XIV", "Louis XV", "Louis XVI"), 1, "Histoire", Difficulty.EASY, explanation = "Louis XIV, dit le Roi-Soleil, a transformé le pavillon de chasse de son père en un immense palais pour centraliser le pouvoir et éloigner la noblesse de Paris."),
        Question(9021, "En quelle année la Bataille de Waterloo s'est-elle déroulée?", listOf("1812", "1815", "1820", "1830"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La bataille de Waterloo, qui a opposé les armées française et anglo-alliée, s'est déroulée le 18 juin 1815 et a marqué la défaite définitive de Napoléon Bonaparte."),
        Question(9022, "Qui a signé la Déclaration d'indépendance américaine?", listOf("Benjamin Franklin", "Thomas Jefferson", "George Washington", "John Adams"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Thomas Jefferson était le principal rédacteur du texte, adopté le 4 juillet 1776 par le Congrès continental."),
        Question(9023, "En quelle année la Révolution russe a-t-elle commencé?", listOf("1905", "1917", "1922", "1925"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La Révolution russe a débuté en février 1917 avec des manifestations à Petrograd, menant à l'abdication du tsar Nicolas II et à la fin de l'Empire russe."),
        Question(9024, "Quel traité a mis fin à la Première Guerre mondiale?", listOf("Traité de Brest-Litovsk", "Traité de Versailles", "Traité de Paris", "Traité de Compiègne"), 1, "Histoire", Difficulty.HARD, explanation = "Signé le 28 juin 1919, le traité de Versailles imposa des conditions sévères à l'Allemagne, notamment des réparations et des pertes territoriales."),
        Question(9025, "En quelle année Hitler a-t-il accédé au pouvoir?", listOf("1930", "1933", "1936", "1939"), 1, "Histoire", Difficulty.EASY, explanation = "Hitler est nommé chancelier le 30 janvier 1933, marquant son accession légale au pouvoir en Allemagne."),
        Question(9026, "Quel événement a déclenché la Première Guerre mondiale?", listOf("L'assassinat de l'Archiduc Franz Ferdinand", "L'invasion de la Belgique", "Le naufrage du Lusitania", "L'attaque de Pearl Harbor"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le 28 juin 1914, l'archiduc François-Ferdinand, héritier du trône austro-hongrois, est assassiné à Sarajevo par un nationaliste serbe, provoquant une crise diplomatique qui mène à la guerre."),
        Question(9027, "En quelle année la Seconde Guerre mondiale a-t-elle commencé?", listOf("1937", "1939", "1941", "1942"), 1, "Histoire", Difficulty.EASY, explanation = "L'invasion de la Pologne par l'Allemagne nazie le 1er septembre 1939 déclencha la Seconde Guerre mondiale, la France et le Royaume-Uni déclarant la guerre à l'Allemagne deux jours plus tard."),
        Question(9028, "Qui était le chef de l'Union soviétique pendant la Seconde Guerre mondiale?", listOf("Lénine", "Trotski", "Staline", "Khrouchtchev"), 2, "Histoire", Difficulty.EASY, explanation = "Joseph Staline dirigeait l'URSS depuis le milieu des années 1920 et était à la tête du pays lors de l'invasion nazie en 1941, menant l'effort de guerre soviétique jusqu'à la victoire en 1945."),
        Question(9029, "En quelle année le Japon a-t-il attaqué Pearl Harbor?", listOf("1940", "1941", "1942", "1943"), 1, "Histoire", Difficulty.EASY, explanation = "L'attaque surprise de Pearl Harbor par le Japon a eu lieu le 7 décembre 1941, provoquant l'entrée des États-Unis dans la Seconde Guerre mondiale."),
        Question(9030, "Quel était le nom du projet de bombe atomique américain?", listOf("Projet Manhattan", "Projet Trinity", "Projet Zeus", "Projet Hercule"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le Projet Manhattan, lancé en 1942, était le nom de code du programme secret américain visant à développer la première bombe atomique, aboutissant aux essais de Trinity et aux bombardements d'Hiroshima et Nagasaki."),
        Question(9031, "En quelle année la bombe atomique a-t-elle été larguée sur Hiroshima?", listOf("1944", "1945", "1946", "1947"), 1, "Histoire", Difficulty.EASY, explanation = "Le largage de la bombe atomique sur Hiroshima a eu lieu le 6 août 1945, pendant la Seconde Guerre mondiale, par les États-Unis contre le Japon."),
        Question(9032, "Qui a livré les discours 'Je ne suis pas un criminel' et 'Vous avez manqué la meilleure chance de votre vie'?", listOf("Harry Truman", "Richard Nixon", "Dwight Eisenhower", "Franklin Roosevelt"), 1, "Histoire", Difficulty.HARD, explanation = "Richard Nixon a prononcé ces discours après sa défaite à l'élection présidentielle de 1962 en Californie, puis lors de sa démission en 1974 suite au scandale du Watergate."),
        Question(9033, "En quelle année la Guerre de Corée a-t-elle commencé?", listOf("1948", "1950", "1952", "1953"), 1, "Histoire", Difficulty.HARD, explanation = "La Guerre de Corée a débuté le 25 juin 1950, lorsque les forces nord-coréennes ont franchi le 38e parallèle, envahissant la Corée du Sud."),
        Question(9034, "Quel mur a été construit pour diviser Berlin?", listOf("Le mur de Hadrien", "Le mur de Berlin", "Le mur de Chine", "Le mur de Jérusalem"), 1, "Histoire", Difficulty.EASY, explanation = "Le mur de Berlin a été érigé en 1961 par la République démocratique allemande pour stopper l'exode massif de ses citoyens vers l'Ouest. Il est devenu le symbole de la guerre froide et de la division de l'Europe."),
        Question(9035, "En quelle année le mur de Berlin est-il tombé?", listOf("1987", "1989", "1991", "1993"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le mur de Berlin est tombé le 9 novembre 1989, marquant la fin de la division de l'Allemagne et un symbole majeur de la chute du bloc soviétique."),
        Question(9036, "Quel événement a marqué le début de la Guerre froide?", listOf("La fin de la Seconde Guerre mondiale", "Le Blocus de Berlin", "Le lancement de Spoutnik", "La Crise des missiles cubains"), 0, "Histoire", Difficulty.HARD, explanation = "La fin de la Seconde Guerre mondiale en 1945 a laissé les États-Unis et l'URSS comme superpuissances rivales, déclenchant des tensions idéologiques et géopolitiques qui ont défini la Guerre froide."),
        Question(9037, "En quelle année l'Union soviétique s'est-elle effondrée?", listOf("1989", "1991", "1993", "1995"), 1, "Histoire", Difficulty.MEDIUM, explanation = "L'URSS s'est officiellement dissoute le 26 décembre 1991, après la démission de Mikhaïl Gorbatchev et la déclaration d'indépendance de plusieurs républiques."),
        Question(9038, "Quel président américain a ordonné l'invasion de la Baie des Cochons?", listOf("Dwight Eisenhower", "John F. Kennedy", "Lyndon B. Johnson", "Richard Nixon"), 1, "Histoire", Difficulty.HARD, explanation = "L'invasion de la Baie des Cochons à Cuba en 1961 a été ordonnée par le président John F. Kennedy, dans le cadre d'une tentative soutenue par la CIA pour renverser le régime de Fidel Castro."),
        Question(9039, "En quelle année la Crise des missiles cubains s'est-elle déroulée?", listOf("1960", "1962", "1965", "1968"), 1, "Histoire", Difficulty.HARD, explanation = "En octobre 1962, l'URSS a installé des missiles nucléaires à Cuba, menant à une confrontation directe avec les États-Unis qui a duré 13 jours."),
        Question(9040, "Qui a été le premier homme à marcher sur la lune?", listOf("Buzz Aldrin", "Neil Armstrong", "Michael Collins", "Alan Bean"), 1, "Histoire", Difficulty.EASY, explanation = "Neil Armstrong a posé le pied sur la Lune le 20 juillet 1969 lors de la mission Apollo 11, marquant un exploit historique pour la NASA et la conquête spatiale."),
        Question(9041, "En quelle année l'homme a-t-il marché sur la lune?", listOf("1967", "1969", "1971", "1972"), 1, "Histoire", Difficulty.EASY, explanation = "La mission Apollo 11 de la NASA a aluné le 20 juillet 1969, avec Neil Armstrong et Buzz Aldrin devenant les premiers humains à marcher sur la Lune."),
        Question(9042, "Quel pharaon égyptien a institué le monothéisme?", listOf("Khéops", "Aménophis IV", "Thoutmosis III", "Ramsès II"), 1, "Histoire", Difficulty.HARD, explanation = "Aménophis IV, plus connu sous le nom d'Akhenaton, a imposé le culte exclusif du dieu Aton, rompant avec le polythéisme traditionnel égyptien."),
        Question(9043, "En quelle année l'Égypte ancienne s'est-elle unie sous un seul pharaon?", listOf("3100 avant J.C.", "2600 avant J.C.", "2100 avant J.C.", "1500 avant J.C."), 0, "Histoire", Difficulty.HARD, explanation = "L'unification de la Haute et de la Basse-Égypte est traditionnellement attribuée au pharaon Narmer (ou Ménès) autour de 3100 avant J.-C., marquant le début de la période dynastique."),
        Question(9044, "Qui était Cléopâtre VII?", listOf("Une déesse égyptienne", "Une reine égyptienne", "Une prêtresse du Nil", "Une danseuse du palais"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Cléopâtre VII fut la dernière souveraine active de l'Égypte ptolémaïque, régnant de 51 à 30 avant J.-C. Elle est célèbre pour ses alliances politiques avec Jules César et Marc Antoine."),
        Question(9045, "En quelle année Cléopâtre a-t-elle rencontré Jules César?", listOf("50 avant J.C.", "48 avant J.C.", "45 avant J.C.", "40 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "Cléopâtre rencontre Jules César en 48 avant J.-C. à Alexandrie, pendant la guerre civile romaine, où elle cherche son soutien pour reconquérir le trône d'Égypte."),
        Question(9046, "Qui a vaincu Cléopâtre et Octave?", listOf("Jules César", "Pompée", "Octave Antoine", "Marc Antoine"), 0, "Histoire", Difficulty.HARD, explanation = "Jules César n'a pas vaincu Cléopâtre et Octave, car Octave était son fils adoptif et son allié. En réalité, c'est Octave (futur Auguste) qui a vaincu Cléopâtre et Marc Antoine à la bataille d'Actium en 31 av. J.-C."),
        Question(9047, "Quel était le plus ancien code de lois écrit?", listOf("Code de Hammourabi", "Lois de Solon", "Lois des Douze Tables", "Lois mosaïques"), 0, "Histoire", Difficulty.HARD, explanation = "Le Code de Hammourabi, gravé sur une stèle de basalte vers 1750 av. J.-C. en Mésopotamie, est l’un des plus anciens recueils de lois écrits connus, comprenant 282 articles."),
        Question(9048, "En quelle année le Code de Hammourabi a-t-il été écrit?", listOf("1900 avant J.C.", "1750 avant J.C.", "1500 avant J.C.", "1200 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "Le Code de Hammourabi, l'un des plus anciens codes de lois écrits, a été rédigé vers 1750 avant J.-C. sous le règne du roi babylonien Hammourabi."),
        Question(9049, "Quel empire a construit l'Aquedu de Pont du Gard?", listOf("L'Empire romain", "L'Empire grec", "L'Empire égyptien", "L'Empire perse"), 0, "Histoire", Difficulty.HARD, explanation = "Le Pont du Gard a été construit par les Romains au Ier siècle après J.-C. pour alimenter en eau la ville de Nîmes via un aqueduc de près de 50 kilomètres."),
        Question(9050, "Qui était Socrate?", listOf("Un général grec", "Un philosophe grec", "Un tyran d'Athènes", "Un dramaturge"), 1, "Histoire", Difficulty.EASY, explanation = "Socrate est un penseur majeur de la Grèce antique, considéré comme le père de la philosophie occidentale pour sa méthode de questionnement."),
        Question(9051, "En quelle année Socrate a-t-il été condamné à mort?", listOf("405 avant J.C.", "400 avant J.C.", "399 avant J.C.", "395 avant J.C."), 2, "Histoire", Difficulty.HARD, explanation = "Socrate fut jugé et condamné à mort par un tribunal athénien en 399 avant J.-C., notamment pour impiété et corruption de la jeunesse."),
        Question(9052, "Qui était Platon?", listOf("Un disciple d'Aristote", "Un disciple de Socrate", "Un général athénien", "Un poète grec"), 1, "Histoire", Difficulty.EASY, explanation = "Platon fut l'élève de Socrate, dont il retranscrivit les dialogues, et le maître d'Aristote, fondant ainsi l'Académie à Athènes."),
        Question(9053, "Quel était le nom du bateau de Christophe Colomb?", listOf("La Nina, La Pinta et la Santa Maria", "La Maria, La Victoria et la Trinidad", "La Rédemption, La Grâce et l'Espérance", "L'Océan, L'Horizon et l'Étoile"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Christophe Colomb a réalisé son premier voyage vers les Amériques en 1492 avec trois navires : la Santa Maria, la Pinta et la Nina."),
        Question(9054, "En quelle année Vasco de Gama a-t-il atteint l'Inde?", listOf("1496", "1498", "1500", "1502"), 1, "Histoire", Difficulty.HARD, explanation = "Vasco de Gama fut le premier Européen à atteindre l'Inde par voie maritime, contournant l'Afrique. Il débarqua à Calicut le 20 mai 1498, ouvrant la route des épices pour le Portugal."),
        Question(9055, "Qui a colonisé la Nouvelle-France?", listOf("Christophe Colomb", "Samuel de Champlain", "Jacques Cartier", "Louis Jolliet"), 1, "Histoire", Difficulty.HARD, explanation = "Samuel de Champlain a fondé Québec en 1608 et est considéré comme le père de la Nouvelle-France, bien que la colonisation ait impliqué plusieurs explorateurs et administrateurs."),
        Question(9056, "En quelle année la Nouvelle-France a-t-elle été fondée?", listOf("1600", "1603", "1605", "1608"), 3, "Histoire", Difficulty.HARD, explanation = "Samuel de Champlain fonda Québec en 1608, établissant le premier établissement permanent français en Amérique du Nord, acte considéré comme la fondation de la Nouvelle-France."),
        Question(9057, "Qui a découvert le Canada?", listOf("Christophe Colomb", "Jean Cabot", "Jacques Cartier", "Samuel de Champlain"), 2, "Histoire", Difficulty.HARD, explanation = "Jacques Cartier, explorateur malouin, a revendiqué le Canada pour la France lors de ses voyages dans le golfe du Saint-Laurent en 1534 et 1535."),
        Question(9058, "En quelle année Jacques Cartier a-t-il exploré le Canada?", listOf("1530", "1534", "1540", "1545"), 1, "Histoire", Difficulty.HARD, explanation = "Jacques Cartier a mené son premier voyage officiel au Canada en 1534, sous le mandat du roi François Ier, pour trouver une route vers l'Asie. Il a ainsi exploré le golfe du Saint-Laurent et pris possession des terres au nom de la France."),
        Question(9059, "Quel était le plus grand empire de l'Histoire?", listOf("L'Empire romain", "L'Empire britannique", "L'Empire mongol", "L'Empire espagnol"), 1, "Histoire", Difficulty.HARD, explanation = "L'Empire britannique est considéré comme le plus vaste de l'Histoire, couvrant à son apogée, au début du XXe siècle, environ un quart des terres émergées et de la population mondiale."),
        Question(9060, "En quelle année l'Empire britannique a-t-il atteint son apogée?", listOf("1880", "1897", "1901", "1914"), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire britannique atteint son extension territoriale maximale en 1901, année de la mort de la reine Victoria, couvrant alors environ un quart des terres émergées."),
        Question(9061, "Qui était Napoléon Bonaparte?", listOf("Un généal français", "Un empereur français", "Un roi français", "Un révolutionnaire français"), 1, "Histoire", Difficulty.EASY, explanation = "Napoléon Bonaparte a été proclamé empereur des Français en 1804, fondant le Premier Empire après avoir été général et Premier consul."),
        Question(9062, "En quelle année Napoléon a-t-il pris le pouvoir en France?", listOf("1795", "1799", "1804", "1810"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Napoléon Bonaparte a pris le pouvoir par le coup d'État du 18 brumaire an VIII, correspondant au 9 novembre 1799, mettant fin au Directoire."),
        Question(9063, "En quelle année Napoléon s'est-il couronné empereur?", listOf("1799", "1801", "1804", "1807"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le sacre de Napoléon Ier a eu lieu le 2 décembre 1804 à Notre-Dame de Paris, établissant le Premier Empire français."),
        Question(9064, "Qui a vaincu Napoléon à Waterloo?", listOf("Le Duc de Wellington", "Alexander Suvorov", "Friedrich Wilhelm III", "Gebhard von Blücher"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le Duc de Wellington commandait les forces britanniques et alliées qui ont défait l'armée de Napoléon le 18 juin 1815 à Waterloo, en Belgique."),
        Question(9065, "En quelle année Napoléon a-t-il été exilé à Sainte-Hélène?", listOf("1814", "1815", "1816", "1820"), 1, "Histoire", Difficulty.HARD, explanation = "Après sa défaite à Waterloo en juin 1815, Napoléon abdique une seconde fois et est exilé par les Britanniques sur l'île de Sainte-Hélène, où il meurt en 1821."),
        Question(9066, "Qui était le Duc de Wellington?", listOf("Un général français", "Un général britannique", "Un général prussien", "Un général autrichien"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Arthur Wellesley, 1er duc de Wellington, commanda les forces britanniques et alliées à la bataille de Waterloo en 1815, où il vainquit Napoléon Bonaparte."),
        Question(9067, "En quelle année le Congrès de Vienne a-t-il eu lieu?", listOf("1812", "1814", "1815", "1816"), 2, "Histoire", Difficulty.HARD, explanation = "Le Congrès de Vienne s'est tenu de septembre 1814 à juin 1815, mais la signature de l'acte final et la clôture officielle eurent lieu le 9 juin 1815."),
        Question(9068, "Quel traité a mis fin à la Révolution française?", listOf("Traité de Paris", "Traité de Versailles", "Traité de Brest-Litovsk", "Traité de Westphalie"), 0, "Histoire", Difficulty.HARD, explanation = "Le Traité de Paris, signé en 1815, a mis fin aux guerres napoléoniennes et stabilisé l'Europe après la Révolution française et l'Empire."),
        Question(9069, "Qui a été le premier consul de France?", listOf("Napoléon Bonaparte", "Paul Barras", "Georges Danton", "Maximilien Robespierre"), 0, "Histoire", Difficulty.HARD, explanation = "Napoléon Bonaparte a été nommé premier consul après le coup d'État du 18 Brumaire en 1799, instaurant le Consulat. Il concentrait alors l'essentiel du pouvoir exécutif."),
        Question(9070, "En quelle année Maximilien Robespierre a-t-il été exécuté?", listOf("1792", "1793", "1794", "1795"), 2, "Histoire", Difficulty.HARD, explanation = "Robespierre, figure majeure de la Révolution française, fut guillotiné le 28 juillet 1794, marquant la fin de la Terreur."),
        Question(9071, "Qui a écrit la Déclaration des Droits de l'Homme et du Citoyen?", listOf("Danton", "Robespierre", "Sieyès", "Jaurès"), 2, "Histoire", Difficulty.HARD, explanation = "L'abbé Sieyès, figure majeure du début de la Révolution française, fut le principal rédacteur de ce texte fondateur adopté en août 1789 par l'Assemblée nationale constituante."),
        Question(9072, "En quelle année la Déclaration des Droits de l'Homme a-t-elle été adoptée?", listOf("1788", "1789", "1791", "1793"), 1, "Histoire", Difficulty.HARD, explanation = "Adoptée le 26 août 1789 par l'Assemblée nationale constituante, cette déclaration est un texte fondamental de la Révolution française."),
        Question(9073, "Quel événement a marqué le début de la Révolution française?", listOf("La prise de la Bastille", "Le serment du Jeu de Paume", "La marche sur Versailles", "La fête de la Fédération"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le 14 juillet 1789, les Parisiens prennent d'assaut la forteresse de la Bastille, symbole de l'arbitraire royal, déclenchant ainsi la Révolution française."),
        Question(9074, "En quelle année la Bastille a-t-elle été prise?", listOf("1787", "1788", "1789", "1790"), 2, "Histoire", Difficulty.EASY, explanation = "La prise de la Bastille, le 14 juillet 1789, marque le début de la Révolution française. Cet événement est célébré comme fête nationale en France."),
        Question(9075, "Qui a inspiré la Révolution française?", listOf("Machiavel", "Montesquieu et Rousseau", "Mably et Condorcet", "Helvetius et Diderot"), 1, "Histoire", Difficulty.HARD, explanation = "Les idées des Lumières de Montesquieu sur la séparation des pouvoirs et de Rousseau sur la souveraineté populaire ont directement influencé les principes de la Révolution française."),
        Question(9076, "En quelle année la Déclaration d'indépendance américaine a-t-elle été signée?", listOf("1774", "1776", "1778", "1783"), 1, "Histoire", Difficulty.EASY, explanation = "Adoptée le 4 juillet 1776 par le Congrès continental, cette déclaration proclame la séparation des treize colonies américaines de la Grande-Bretagne."),
        Question(9077, "Quel est le nom du premier ministre britannique?", listOf("Earl of North", "William Pitt le Jeune", "Edmund Burke", "Charles James Fox"), 0, "Histoire", Difficulty.HARD, explanation = "Le titre de Premier ministre britannique est informel à l'origine ; Robert Walpole, chef du cabinet sous George Ier et George II, est considéré comme le premier à occuper cette fonction, souvent appelé Lord North par métonymie."),
        Question(9078, "En quelle année la Guerre d'indépendance américaine a-t-elle commencé?", listOf("1773", "1775", "1776", "1781"), 1, "Histoire", Difficulty.HARD, explanation = "Les premiers affrontements armés entre les colons américains et les troupes britanniques eurent lieu en 1775, notamment aux batailles de Lexington et Concord."),
        Question(9079, "Qui a commandé l'armée continentale pendant la Guerre d'indépendance?", listOf("Benjamin Franklin", "George Washington", "John Adams", "Thomas Jefferson"), 1, "Histoire", Difficulty.MEDIUM, explanation = "George Washington fut nommé commandant en chef de l'armée continentale par le Congrès continental en 1775, dirigeant les forces américaines jusqu'à la victoire de Yorktown en 1781."),
        Question(9080, "En quelle année la Guerre d'indépendance américaine a-t-elle pris fin?", listOf("1781", "1783", "1785", "1787"), 1, "Histoire", Difficulty.HARD, explanation = "Le traité de Paris, signé le 3 septembre 1783, mit officiellement fin à la guerre d'indépendance américaine entre la Grande-Bretagne et les États-Unis."),
        Question(9081, "Quel philosophe grec a fondé l'Académie?", listOf("Aristote", "Platon", "Socrate", "Pythagore"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Platon fonda l'Académie d'Athènes vers 387 av. J.-C., une école philosophique majeure de l'Antiquité."),
        Question(9082, "En quelle année Aristote est-il né?", listOf("385 avant J.C.", "384 avant J.C.", "383 avant J.C.", "382 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "Aristote, philosophe grec majeur, est né en 384 avant J.-C. à Stagire, en Macédoine."),
        Question(9083, "Quel poète grec a écrit l'Odyssée?", listOf("Hésiode", "Homère", "Théocrite", "Pindare"), 1, "Histoire", Difficulty.EASY, explanation = "Homère est traditionnellement considéré comme l'auteur de l'Odyssée et de l'Iliade, deux épopées fondatrices de la littérature grecque antique."),
        Question(9084, "En quelle année le Collège Britannique a-t-il été fondé?", listOf("1636", "1650", "1680", "1700"), 0, "Histoire", Difficulty.HARD, explanation = "Le Collège Britannique, connu aujourd'hui sous le nom de Harvard University, a été fondé en 1636 par la colonie de la baie du Massachusetts. C'est la plus ancienne institution d'enseignement supérieur des États-Unis."),
        Question(9085, "Qui était Léonard de Vinci?", listOf("Un peintre", "Un mathématicien", "Un ingénieur", "Tous les trois"), 3, "Histoire", Difficulty.EASY, explanation = "Léonard de Vinci était un peintre, sculpteur, architecte, scientifique et inventeur de la Renaissance italienne, ce qui en fait un artiste, un scientifique et un ingénieur à la fois."),
        Question(9086, "En quelle année Léonard de Vinci a-t-il peint la Joconde?", listOf("1503", "1509", "1515", "1519"), 0, "Histoire", Difficulty.HARD, explanation = "La Joconde a été commencée par Léonard de Vinci vers 1503, alors qu'il travaillait à Florence, bien que le tableau ait été retouché jusqu'à sa mort en 1519."),
        Question(9087, "Quel was le père de Léonard de Vinci?", listOf("Ser Piero da Vinci", "Ser Leonardo da Vinci", "Ser Vinci da Vinci", "Ser Andrea da Vinci"), 0, "Histoire", Difficulty.HARD, explanation = "Ser Piero da Vinci était un notaire florentin, père de Léonard. Léonard est né de sa relation illégitime avec une paysanne, Caterina."),
        Question(9088, "Qui était Michel-Ange?", listOf("Un sculpteur", "Un peintre", "Un architecte", "Tous les trois"), 3, "Histoire", Difficulty.EASY, explanation = "Michel-Ange était un peintre, sculpteur, architecte et poète de la Renaissance italienne, célèbre pour des œuvres comme la fresque de la chapelle Sixtine et la statue de David."),
        Question(9089, "En quelle année Michel-Ange a-t-il commencé la Chapelle Sixtine?", listOf("1508", "1510", "1512", "1515"), 0, "Histoire", Difficulty.HARD, explanation = "Michel-Ange a commencé la fresque du plafond de la Chapelle Sixtine en 1508, commandée par le pape Jules II. Il y travailla jusqu'en 1512."),
        Question(9090, "Quel était le sujet principal de la Chapelle Sixtine?", listOf("La création du monde", "La passion de Jésus-Christ", "La résurrection", "L'apocalypse"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le plafond de la Chapelle Sixtine, peint par Michel-Ange entre 1508 et 1512, illustre principalement des scènes de la Genèse, dont la création du monde par Dieu."),
        Question(9091, "Qui était Raphaël?", listOf("Un sculpteur italien", "Un peintre italien", "Un architecte italien", "Un poète italien"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Raphaël (Raffaello Sanzio) est un peintre et architecte majeur de la Renaissance italienne, célèbre pour ses fresques au Vatican et ses madones."),
        Question(9092, "En quelle année Raphaël a-t-il peint l'École d'Athènes?", listOf("1508", "1510", "1511", "1514"), 2, "Histoire", Difficulty.HARD, explanation = "Raphaël a peint L'École d'Athènes entre 1509 et 1511 dans les chambres du Vatican, commandée par le pape Jules II. Cette fresque incarne l'esprit de la Renaissance en réunissant les grands philosophes de l'Antiquité."),
        Question(9093, "Quel est le titre du chef-d'œuvre de Dante?", listOf("Le Paradis perdu", "La Comédie divine", "L'Enéide", "Le Décaméron"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Dante a intitulé son poème épique simplement Comédie, car il commence dans la tristesse et se termine dans la joie. L'adjectif divine a été ajouté par Boccace au XIVe siècle."),
        Question(9094, "En quelle année Dante a-t-il écrit La Comédie divine?", listOf("1290", "1300", "1310", "1320"), 2, "Histoire", Difficulty.HARD, explanation = "Dante a commencé à écrire La Divine Comédie vers 1307, mais l'œuvre a été principalement composée entre 1310 et sa mort en 1321. La date de 1310 marque le début de la rédaction de l'Enfer, la première partie du poème."),
        Question(9095, "Qui était Copernic?", listOf("Un astronome polonais", "Un astronome italien", "Un astronome allemand", "Un astronome danois"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Nicolas Copernic est le premier astronome à avoir formulé le modèle héliocentrique du système solaire, plaçant le Soleil au centre et non la Terre."),
        Question(9096, "En quelle année Copernic a-t-il présenté l'héliocentrisme?", listOf("1520", "1540", "1543", "1600"), 2, "Histoire", Difficulty.HARD, explanation = "Nicolas Copernic publie son ouvrage majeur \"De revolutionibus orbium coelestium\" en 1543, année de sa mort, où il expose la théorie héliocentrique plaçant le Soleil au centre de l'univers."),
        Question(9097, "Qui était Galilée?", listOf("Un physicien", "Un astronome", "Un mathématicien", "Tous les trois"), 3, "Histoire", Difficulty.MEDIUM, explanation = "Galilée était à la fois un astronome, un physicien et un mathématicien italien du XVIIe siècle, pionnier de la méthode scientifique moderne."),
        Question(9098, "En quelle année Galilée a-t-il été assigné à résidence?", listOf("1630", "1633", "1636", "1640"), 1, "Histoire", Difficulty.HARD, explanation = "En 1633, l'Inquisition a condamné Galilée pour avoir soutenu la théorie héliocentrique de Copernic, jugée contraire aux Écritures. Il a été contraint de se rétracter et assigné à résidence jusqu'à sa mort."),
        Question(9099, "Quel invention a révolutionné l'observation du ciel?", listOf("Le télescope", "Le microscope", "L'astrolabe", "Le quadrant"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le télescope, inventé au début du XVIIe siècle, a permis d'observer des astres invisibles à l'œil nu, transformant l'astronomie."),
        Question(9100, "Qui a inventé le télescope?", listOf("Galilée", "Kepler", "Huygens", "Newton"), 0, "Histoire", Difficulty.HARD, explanation = "Galilée a perfectionné le télescope en 1609, mais le premier modèle a été inventé par l'opticien néerlandais Hans Lippershey en 1608."),
        Question(9101, "En quelle année Isaac Newton a-t-il découvert la gravité?", listOf("1665", "1666", "1687", "1689"), 2, "Histoire", Difficulty.HARD, explanation = "Newton a formulé sa loi de la gravitation universelle dans son ouvrage Philosophiæ Naturalis Principia Mathematica, publié en 1687."),
        Question(9102, "Quel était le principal philosophe des Lumières français?", listOf("Voltaire", "Montesquieu", "Rousseau", "Diderot"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Voltaire est considéré comme le principal philosophe des Lumières français en raison de son influence majeure sur la pensée critique, la défense de la liberté d'expression et la critique des institutions religieuses et politiques de son époque."),
        Question(9103, "En quelle année Voltaire a-t-il écrit 'Candide'?", listOf("1755", "1757", "1759", "1762"), 2, "Histoire", Difficulty.HARD, explanation = "Voltaire publie Candide en 1759, satire mordante de l'optimisme philosophique de Leibniz, après le tremblement de terre de Lisbonne de 1755."),
        Question(9104, "Qui était l'auteur de 'Du Contrat social'?", listOf("Montesquieu", "Rousseau", "Diderot", "Helvétius"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Rousseau publie Du Contrat social en 1762, ouvrage fondateur de la philosophie politique moderne qui inspire les idéaux républicains et la Révolution française."),
        Question(9105, "En quelle année Jean-Jacques Rousseau a-t-il écrit 'Du Contrat social'?", listOf("1750", "1758", "1760", "1762"), 3, "Histoire", Difficulty.HARD, explanation = "1762 est l'année de publication du 'Du Contrat social', une œuvre majeure de philosophie politique de Jean-Jacques Rousseau."),
        Question(9106, "Qui a écrit l'Encyclopédie?", listOf("Voltaire et Rousseau", "Diderot et d'Alembert", "Montesquieu et Helvétius", "Condillac et Condorcet"), 1, "Histoire", Difficulty.HARD, explanation = "L'Encyclopédie a été dirigée par Denis Diderot et Jean le Rond d'Alembert, ce dernier en étant le coéditeur scientifique jusqu'en 1758. Cette œuvre majeure des Lumières visait à rassembler et diffuser les connaissances de l'époque."),
        Question(9107, "En quelle année l'Encyclopédie a-t-elle commencé sa publication?", listOf("1740", "1745", "1751", "1755"), 2, "Histoire", Difficulty.HARD, explanation = "L'Encyclopédie, dirigée par Diderot et d'Alembert, a publié son premier volume en 1751. Cette œuvre majeure des Lumières visait à rassembler et diffuser les connaissances de l'époque."),
        Question(9108, "Quel événement a marqué la fin du Moyen Âge?", listOf("La chute de Constantinople", "La prise de la Bastille", "La découverte de l'Amérique", "La Renaissance"), 0, "Histoire", Difficulty.HARD, explanation = "La chute de Constantinople en 1453 marque traditionnellement la fin du Moyen Âge, car elle met fin à l'Empire byzantin et bouleverse l'équilibre géopolitique et culturel de l'Europe."),
        Question(9109, "En quelle année Constantinople est-elle tombée?", listOf("1449", "1450", "1453", "1456"), 2, "Histoire", Difficulty.HARD, explanation = "La chute de Constantinople en 1453 marque la fin de l'Empire byzantin après le siège mené par le sultan ottoman Mehmed II."),
        Question(9110, "Qui a conquis Constantinople en 1453?", listOf("Murad II", "Mehmed II", "Süleyman le Magnifique", "Ibrahim Pacha"), 1, "Histoire", Difficulty.HARD, explanation = "Mehmed II, sultan ottoman, a conquis Constantinople en 1453 après un siège de 53 jours, mettant fin à l'Empire byzantin."),
        Question(9111, "Quel était l'empire qui a conquis Constantinople?", listOf("L'Empire ottoman", "L'Empire mongol", "L'Empire persan", "L'Empire arabe"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Les Ottomans, dirigés par le sultan Mehmed II, ont pris Constantinople en 1453 après un siège de 53 jours, mettant fin à l'Empire byzantin."),
        Question(9112, "En quelle année la Renaissance a-t-elle commencé en Italie?", listOf("1300", "1350", "1400", "1450"), 2, "Histoire", Difficulty.HARD, explanation = "La Renaissance italienne est généralement considérée comme ayant débuté au début du XVe siècle, vers 1400, avec l'émergence de l'humanisme et des innovations artistiques à Florence."),
        Question(9113, "Quelle ville italienne a été le berceau de la Renaissance?", listOf("Rome", "Florence", "Venise", "Milan"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Florence, sous la domination des Médicis, est devenue au XVe siècle le centre intellectuel et artistique de l'Europe, abritant des génies comme Léonard de Vinci et Michel-Ange."),
        Question(9114, "Quel était le nom de la famille qui contrôlait Florence pendant la Renaissance?", listOf("Les Borgia", "Les Médicis", "Les Visconti", "Les Doria"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La famille Médicis a dominé Florence du XVe au XVIIIe siècle grâce à sa puissance bancaire et son mécénat artistique, finançant des figures comme Léonard de Vinci et Michel-Ange."),
        Question(9115, "En quelle année les Médicis ont-ils pris le pouvoir à Florence?", listOf("1400", "1434", "1469", "1494"), 1, "Histoire", Difficulty.HARD, explanation = "Cosme de Médicis revient d'exil en 1434 et prend la tête de la République florentine, marquant le début de la domination politique de sa famille."),
        Question(9116, "Qui était Laurent le Magnifique?", listOf("Un pape", "Un Médicis florentin", "Un doge vénitien", "Un duc milanais"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Laurent le Magnifique était un homme d'État et mécène italien de la Renaissance, membre influent de la famille Médicis qui gouverna Florence."),
        Question(9117, "En quelle année Laurent le Magnifique a-t-il été assassiné?", listOf("1478", "1492", "1500", "1510"), 0, "Histoire", Difficulty.HARD, explanation = "Laurent de Médicis survit à l'attentat de la conjuration des Pazzi en 1478, mais son frère Julien est tué."),
        Question(9118, "Quel événement a marqué le début du Moyen Âge?", listOf("La chute de l'Empire romain", "L'invasion des Barbares", "La mort de Jules César", "La montée du Christianisme"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La chute de l'Empire romain d'Occident en 476 marque conventionnellement le début du Moyen Âge, car elle entraîne la fin de l'Antiquité et l'émergence de nouvelles structures politiques et sociales en Europe."),
        Question(9119, "En quelle année l'Empire romain d'Occident est-il tombé?", listOf("410", "476", "527", "565"), 1, "Histoire", Difficulty.HARD, explanation = "476 marque la déposition du dernier empereur romain d'Occident, Romulus Augustule, par le chef barbare Odoacre, mettant fin à l'Empire romain d'Occident."),
        Question(9120, "Qui a été le premier roi des Francs?", listOf("Clovis", "Pépin le Bref", "Charlemagne", "Louis le Pieux"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Clovis Ier est considéré comme le premier roi des Francs car il unifia les tribus franques au Ve siècle et fonda la dynastie mérovingienne."),
        Question(9121, "En quelle année Clovis a-t-il uni les royaumes francs?", listOf("480", "500", "507", "514"), 2, "Histoire", Difficulty.HARD, explanation = "Clovis a unifié les royaumes francs après sa victoire sur les Wisigoths à la bataille de Vouillé en 507, ce qui lui a permis de contrôler la majeure partie de la Gaule."),
        Question(9122, "Qui a fondé la dynastie carolingienne?", listOf("Clovis", "Pépin le Bref", "Charles Martel", "Charlemagne"), 1, "Histoire", Difficulty.HARD, explanation = "Pépin le Bref, fils de Charles Martel, déposa le dernier roi mérovingien en 751 et se fit sacrer roi, fondant ainsi la dynastie carolingienne."),
        Question(9123, "En quelle année Pépin le Bref a-t-il fondé la dynastie carolingienne?", listOf("748", "751", "768", "771"), 1, "Histoire", Difficulty.HARD, explanation = "Pépin le Bref fut élu roi des Francs en 751, déposant le dernier Mérovingien, Childéric III. Cet événement marque le début officiel de la dynastie carolingienne."),
        Question(9124, "Qui était Charlemagne?", listOf("Un roi franc", "Un empereur des Romains", "Un pape", "Tous les deux premiers"), 3, "Histoire", Difficulty.EASY, explanation = "Charlemagne est à la fois roi des Francs et empereur d'Occident, couronné en 800. Les deux premières réponses (roi des Francs et empereur) sont donc correctes."),
        Question(9125, "En quelle année Charlemagne a-t-il été couronné empereur?", listOf("768", "800", "814", "820"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le pape Léon III couronna Charlemagne empereur à Rome le 25 décembre 800, restauré le titre impérial en Occident."),
        Question(9126, "Qui a été le fondateur de la Renaissance française?", listOf("Louis XII", "François Ier", "Henri II", "Henri IV"), 1, "Histoire", Difficulty.HARD, explanation = "François Ier est considéré comme le fondateur de la Renaissance française car il a introduit l'art italien en France, notamment en invitant Léonard de Vinci à sa cour."),
        Question(9127, "En quelle année François Ier a-t-il pris le pouvoir?", listOf("1515", "1520", "1525", "1530"), 0, "Histoire", Difficulty.HARD, explanation = "François Ier succède à Louis XII en 1515, année de son sacre à Reims et de sa célèbre victoire à Marignan."),
        Question(9128, "Quel événement a marqué la fin de la Guerre de Cent Ans?", listOf("Le siège d'Orléans", "La bataille d'Azincourt", "Le Traité de Troyes", "Le Traité de Paris"), 0, "Histoire", Difficulty.HARD, explanation = "Le siège d'Orléans en 1429, marqué par l'intervention de Jeanne d'Arc, fut un tournant décisif qui permit aux Français de reprendre l'offensive, mais la guerre ne s'acheva officiellement qu'en 1453 avec la bataille de Castillon."),
        Question(9129, "En quelle année la Guerre de Cent Ans a-t-elle pris fin?", listOf("1430", "1450", "1453", "1461"), 2, "Histoire", Difficulty.HARD, explanation = "La guerre de Cent Ans s'achève en 1453 avec la bataille de Castillon, où les Français remportent une victoire décisive sur les Anglais, mettant fin au conflit qui durait depuis 1337."),
        Question(9130, "Quel roi anglais a été le plus grand combattant de la Guerre de Cent Ans?", listOf("Édouard III", "Henri V", "Édouard IV", "Richard II"), 1, "Histoire", Difficulty.HARD, explanation = "Henri V d'Angleterre remporta la célèbre bataille d'Azincourt en 1415, une victoire écrasante qui lui permit de conquérir une grande partie de la France et d'être reconnu comme héritier du trône français par le traité de Troyes."),
        Question(9131, "En quelle année la Bataille d'Azincourt s'est-elle déroulée?", listOf("1415", "1420", "1425", "1430"), 0, "Histoire", Difficulty.HARD, explanation = "La bataille d'Azincourt a eu lieu le 25 octobre 1415, pendant la guerre de Cent Ans, opposant l'armée anglaise d'Henri V aux forces françaises."),
        Question(9132, "Qui a commandé l'armée française à la Bataille d'Azincourt?", listOf("Charles VI", "Charles VII", "Jean de Dunois", "Jean sans Terre"), 0, "Histoire", Difficulty.HARD, explanation = "Charles VI était roi de France lors de la bataille d'Azincourt en 1415, mais il souffrait de troubles mentaux et n'a pas commandé directement l'armée, confiée au connétable Charles d'Albret."),
        Question(9133, "Quel était le surnom de Jeanne d'Arc?", listOf("La Maid d'Orléans", "La Pucelle d'Orléans", "L'Héroïne de la France", "La Sainte Jeanne"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Jeanne d'Arc, une jeune paysanne, mena l'armée française à la victoire contre les Anglais lors du siège d'Orléans en 1429, ce qui lui valut le surnom de \"La Pucelle d'Orléans\"."),
        Question(9134, "En quelle année Jeanne d'Arc a-t-elle été capturée?", listOf("1429", "1430", "1431", "1432"), 1, "Histoire", Difficulty.HARD, explanation = "Jeanne d'Arc a été capturée par les Bourguignons le 23 mai 1430 lors du siège de Compiègne, pendant la guerre de Cent Ans."),
        Question(9135, "Qui a capturé Jeanne d'Arc?", listOf("Les Anglais", "Les Bourguignons", "Les Français", "Les Allemands"), 1, "Histoire", Difficulty.HARD, explanation = "Jeanne d'Arc a été capturée à Compiègne en 1430 par des soldats du duc de Bourgogne, alliés des Anglais pendant la guerre de Cent Ans."),
        Question(9136, "Qui a jugé Jeanne d'Arc?", listOf("Le roi de France", "L'Inquisition espagnole", "L'évêque de Beauvais", "Le Pape"), 2, "Histoire", Difficulty.HARD, explanation = "Le procès de Jeanne d'Arc en 1431 fut mené par Pierre Cauchon, évêque de Beauvais, qui agissait sous l'autorité des Anglais pour la condamner pour hérésie."),
        Question(9137, "En quelle année le Traité de Cateau-Cambrésis a-t-il été signé?", listOf("1555", "1559", "1565", "1570"), 1, "Histoire", Difficulty.HARD, explanation = "Ce traité mit fin aux guerres d'Italie entre la France et l'Espagne, consacrant l'hégémonie espagnole en Europe."),
        Question(9138, "Quel traité a mis fin aux guerres d'Italie?", listOf("Traité de Madrid", "Traité de Cateau-Cambrésis", "Traité de Naples", "Traité de Blois"), 1, "Histoire", Difficulty.HARD, explanation = "Le traité de Cateau-Cambrésis, signé en 1559, mit fin aux guerres d'Italie entre la France et l'Espagne, établissant la domination espagnole sur la péninsule italienne."),
        Question(9139, "En quelle année les Guerres de religion ont-elles commencé en France?", listOf("1560", "1562", "1567", "1572"), 1, "Histoire", Difficulty.HARD, explanation = "Les Guerres de religion françaises débutent en 1562 avec le massacre de Wassy, où des soldats du duc de Guise tuent des protestants. Ce conflit oppose catholiques et protestants jusqu'en 1598."),
        Question(9140, "En quelle année le Massacre de la Saint-Barthélemy s'est-il produit?", listOf("1570", "1572", "1575", "1577"), 1, "Histoire", Difficulty.HARD, explanation = "Le massacre des protestants par les catholiques à Paris a débuté le 24 août 1572, pendant les guerres de Religion, quelques jours après le mariage d'Henri de Navarre."),
        Question(9141, "Qui a orchestré le Massacre de la Saint-Barthélemy?", listOf("Catherine de Médicis", "Henri de Valois", "Henri de Navarre", "Le duc de Guise"), 0, "Histoire", Difficulty.HARD, explanation = "Catherine de Médicis, reine mère et régente, ordonna le massacre des chefs protestants pour préserver l'autorité royale après l'échec d'une tentative d'assassinat contre l'amiral de Coligny."),
        Question(9142, "Quel traité a mis fin aux Guerres de religion en France?", listOf("Traité de Paris", "Édit de Nantes", "Traité de Cateau-Cambrésis", "Paix d'Amiens"), 1, "Histoire", Difficulty.HARD, explanation = "Signé en 1598 par Henri IV, l'édit de Nantes accordait une liberté de culte limitée aux protestants, mettant fin à plusieurs décennies de conflits religieux en France."),
        Question(9143, "En quelle année l'Édit de Nantes a-t-il été signé?", listOf("1598", "1600", "1605", "1610"), 0, "Histoire", Difficulty.HARD, explanation = "L'Édit de Nantes, signé en 1598 par Henri IV, mit fin aux guerres de Religion en accordant une tolérance limitée aux protestants."),
        Question(9144, "Qui a signé l'Édit de Nantes?", listOf("Henri III", "Henri IV", "Louis XIII", "Louis XIV"), 1, "Histoire", Difficulty.HARD, explanation = "Henri IV signa l'édit de Nantes en 1598 pour mettre fin aux guerres de Religion entre catholiques et protestants, accordant une certaine liberté de culte aux huguenots."),
        Question(9145, "Quel événement a marqué le début de l'Inquisition espagnole?", listOf("L'expulsion des Juifs", "La Reconquista", "L'établissement du tribunal", "L'unification de l'Espagne"), 2, "Histoire", Difficulty.HARD, explanation = "En 1478, les Rois Catholiques obtiennent du pape Sixte IV l'autorisation d'établir un tribunal pour traquer les hérétiques, marquant le début officiel de l'Inquisition espagnole."),
        Question(9146, "En quelle année l'Inquisition espagnole a-t-elle été établie?", listOf("1478", "1492", "1500", "1515"), 0, "Histoire", Difficulty.HARD, explanation = "L'Inquisition espagnole a été créée en 1478 par les Rois Catholiques, Ferdinand d'Aragon et Isabelle de Castille, pour maintenir l'orthodoxie catholique dans leurs royaumes."),
        Question(9147, "Qui a dirigé l'Inquisition espagnole?", listOf("Torquemada", "Cardinal Jiménez", "Le Roi Ferdinand", "Le Pape"), 0, "Histoire", Difficulty.HARD, explanation = "Tomás de Torquemada, dominicain espagnol, fut le premier Grand Inquisiteur nommé par les Rois Catholiques en 1483, dirigeant l'Inquisition espagnole avec une sévérité extrême."),
        Question(9148, "En quelle année les Juifs ont-ils été expulsés d'Espagne?", listOf("1480", "1492", "1510", "1550"), 1, "Histoire", Difficulty.HARD, explanation = "En 1492, les Rois Catholiques Ferdinand et Isabelle ont signé le décret de l'Alhambra, ordonnant l'expulsion des Juifs d'Espagne sous peine de conversion forcée."),
        Question(9149, "Qui a exploré la côte de l'Afrique?", listOf("Christophe Colomb", "Henri le Navigateur", "Vasco de Gama", "Bartolomeu Dias"), 1, "Histoire", Difficulty.HARD, explanation = "Henri le Navigateur, prince portugais, a financé et organisé les premières expéditions maritimes le long de la côte africaine au XVe siècle, ouvrant la voie à l'exploration européenne."),
        Question(9150, "En quelle année Henri le Navigateur a-t-il commencé ses explorations?", listOf("1410", "1420", "1430", "1440"), 0, "Histoire", Difficulty.HARD, explanation = "Henri le Navigateur, prince portugais, a lancé les premières expéditions maritimes vers l'Afrique en 1410, marquant le début de l'ère des grandes découvertes portugaises."),
        Question(9151, "Qui a découvert la route maritime vers l'Inde?", listOf("Christophe Colomb", "Vasco de Gama", "Bartolomeu Dias", "Ferdinand de Magellan"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Vasco de Gama fut le premier Européen à atteindre l'Inde par voie maritime en 1498, contournant l'Afrique via le cap de Bonne-Espérance pour le Portugal."),
        Question(9152, "En quelle année Vasco de Gama a-t-il atteint l'Inde pour la première fois?", listOf("1495", "1498", "1502", "1505"), 1, "Histoire", Difficulty.HARD, explanation = "Vasco de Gama atteint Calicut, en Inde, en 1498, ouvrant la route maritime européenne vers l'Asie en contournant l'Afrique."),
        Question(9153, "Quel explorateur a complété le premier tour du monde?", listOf("Christophe Colomb", "Vasco de Gama", "Ferdinand de Magellan", "Jean Cartier"), 2, "Histoire", Difficulty.HARD, explanation = "L'expédition de Magellan, partie en 1519, fut la première à accomplir la circumnavigation du globe, bien que Magellan lui-même soit mort aux Philippines en 1521."),
        Question(9154, "En quelle année le voyage de Magellan autour du monde a-t-il commencé?", listOf("1519", "1520", "1521", "1522"), 0, "Histoire", Difficulty.HARD, explanation = "Le navigateur portugais Fernand de Magellan a quitté l'Espagne en septembre 1519 avec cinq navires, marquant le début de la première circumnavigation du globe, qu'il n'achèvera pas lui-même."),
        Question(9155, "Qui a complété le voyage autour du monde après la mort de Magellan?", listOf("Juan Sebastián Elcano", "António de Albuquerque", "Bartolomeu Dias", "Fernão Mendes Pinto"), 0, "Histoire", Difficulty.HARD, explanation = "Juan Sebastián Elcano prit le commandement de l'expédition après la mort de Magellan aux Philippines en 1521 et ramena le navire Victoria en Espagne en 1522, achevant ainsi le premier tour du monde."),
        Question(9156, "En quelle année le voyage autour du monde a-t-il été complété?", listOf("1520", "1521", "1522", "1523"), 2, "Histoire", Difficulty.HARD, explanation = "Le premier tour du monde, initié par Magellan, fut achevé en 1522 sous le commandement de Juan Sebastián Elcano après la mort de Magellan aux Philippines."),
        Question(9157, "Quel est le plus ancien code légal connu?", listOf("Code de Justinien", "Lois des Douze Tables", "Code de Hammourabi", "Lois mosaïques"), 2, "Histoire", Difficulty.HARD, explanation = "Le Code de Hammourabi, gravé sur une stèle de basalte vers 1750 av. J.-C. en Mésopotamie, est le plus ancien recueil de lois complet découvert."),
        Question(9158, "Qui a établi le Code de Justinien?", listOf("Auguste", "Justinien Ier", "Théodose Ier", "Constantin"), 1, "Histoire", Difficulty.HARD, explanation = "Justinien Ier, empereur byzantin, ordonna la compilation et la réforme du droit romain au VIe siècle, aboutissant au Corpus Juris Civilis, dont le Code fait partie."),
        Question(9159, "En quelle année le Code de Justinien a-t-il été compilé?", listOf("528", "532", "536", "540"), 1, "Histoire", Difficulty.HARD, explanation = "Le Code de Justinien, compilation du droit romain, a été promulgué en 532 sous l'empereur byzantin Justinien Ier, visant à unifier et clarifier les lois."),
        Question(9160, "Quel était le nom original de la Turquie?", listOf("Asie mineure", "Anatolie", "Périclès", "Thrace"), 1, "Histoire", Difficulty.HARD, explanation = "Le nom Anatolie désignait la région asiatique de l'actuelle Turquie avant la fondation de la République turque en 1923."),
        Question(9161, "En quelle année la Turquie moderne a-t-elle été fondée?", listOf("1920", "1923", "1925", "1930"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Mustafa Kemal Atatürk proclama la République de Turquie le 29 octobre 1923, mettant fin à l'Empire ottoman et fondant l'État turc moderne et laïc."),
        Question(9162, "Qui a fondé la Turquie moderne?", listOf("Mehmed II", "Mustafa Kemal Atatürk", "Süleyman le Magnifique", "Mehmed VI"), 1, "Histoire", Difficulty.HARD, explanation = "Mustafa Kemal Atatürk a fondé la République de Turquie en 1923 après la guerre d'indépendance turque, modernisant le pays par des réformes politiques, sociales et culturelles radicales."),
        Question(9163, "En quelle année la Grande Muraille de Chine a-t-elle été terminée?", listOf("1644", "1644", "1644", "1644"), 3, "Histoire", Difficulty.HARD, explanation = "La construction de la Grande Muraille s'est étalée sur plusieurs dynasties, mais sa forme actuelle date de la dynastie Ming, qui s'est achevée en 1644."),
        Question(9164, "Qui a commandé la construction de la Grande Muraille?", listOf("Qin Shi Huang", "Kangxi", "Yongzheng", "Qianlong"), 0, "Histoire", Difficulty.HARD, explanation = "Qin Shi Huang, premier empereur de Chine unifiée, ordonna la construction de la Grande Muraille pour protéger son territoire des invasions nomades venues du nord."),
        Question(9165, "En quelle année la Dynastie Ming a-t-elle commencé?", listOf("1344", "1368", "1388", "1405"), 1, "Histoire", Difficulty.HARD, explanation = "La dynastie Ming a débuté en 1368 lorsque Zhu Yuanzhang a renversé la dynastie mongole Yuan et s'est proclamé empereur, fondant ainsi une nouvelle ère impériale chinoise."),
        Question(9166, "En quelle année la Dynastie Ming s'est-elle terminée?", listOf("1644", "1661", "1683", "1722"), 0, "Histoire", Difficulty.HARD, explanation = "La dynastie Ming s'est effondrée en 1644 lorsque Pékin a été prise par les rebelles de Li Zicheng, marquant la fin de son règne et l'arrivée de la dynastie Qing."),
        Question(9167, "Quel était le fondateur de la Dynastie Ming?", listOf("Kangxi", "Yongzheng", "Zhu Yuanzhang", "Zhu De"), 2, "Histoire", Difficulty.HARD, explanation = "Zhu Yuanzhang, un ancien paysan, mena la révolte qui renversa la dynastie mongole Yuan et fonda la dynastie Ming en 1368, devenant l'empereur Hongwu."),
        Question(9168, "En quelle année les Cités-États grecques ont-elles été unifiées?", listOf("338 avant J.C.", "320 avant J.C.", "300 avant J.C.", "280 avant J.C."), 0, "Histoire", Difficulty.HARD, explanation = "Philippe II de Macédoine a unifié les Cités-États grecques en 338 av. J.-C. après sa victoire à la bataille de Chéronée, mettant fin à leur indépendance."),
        Question(9169, "Qui a unifié les Cités-États grecques?", listOf("Philippe II", "Alexandre le Grand", "Démosthène", "Périclès"), 0, "Histoire", Difficulty.HARD, explanation = "Philippe II de Macédoine a unifié les cités-États grecques en les soumettant militairement après la bataille de Chéronée en 338 av. J.-C., créant la Ligue de Corinthe sous son hégémonie."),
        Question(9170, "En quelle année la Bataille de Marathon s'est-elle déroulée?", listOf("492 avant J.C.", "490 avant J.C.", "480 avant J.C.", "470 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Marathon en 490 avant J.-C. oppose les Athéniens aux Perses lors de la première guerre médique. Cette victoire grecque stoppe temporairement l'expansion perse en Europe."),
        Question(9171, "Quel était le chef des Perses lors de la Bataille de Marathon?", listOf("Cyrus II", "Darius Ier", "Xerxès Ier", "Artaxerxès"), 1, "Histoire", Difficulty.HARD, explanation = "Darius Ier était le roi de l'Empire perse et a ordonné l'invasion de la Grèce, menant à la bataille de Marathon en 490 av. J.-C., où les Athéniens ont remporté une victoire décisive."),
        Question(9172, "En quelle année la Bataille de Salamine s'est-elle déroulée?", listOf("490 avant J.C.", "480 avant J.C.", "470 avant J.C.", "450 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Salamine opposa la flotte grecque à celle de l'Empire perse en 480 avant J.-C., dans le cadre de la seconde guerre médique. Cette victoire navale grecque marqua un tournant décisif contre l'invasion perse menée par Xerxès Ier."),
        Question(9173, "Qui a commandé la flotte grecque à la Bataille de Salamine?", listOf("Périclès", "Thémistocle", "Léonidas", "Miltiade"), 1, "Histoire", Difficulty.HARD, explanation = "Thémistocle, stratège athénien, commandait la flotte grecque unifiée lors de la bataille de Salamine en 480 av. J.-C., où il utilisa une ruse pour attirer les Perses dans le détroit étroit."),
        Question(9174, "En quelle année la Bataille des Thermopyles s'est-elle déroulée?", listOf("492 avant J.C.", "490 avant J.C.", "480 avant J.C.", "470 avant J.C."), 2, "Histoire", Difficulty.HARD, explanation = "La Bataille des Thermopyles a eu lieu en 480 avant J.-C., durant la seconde guerre médique, opposant une coalition de cités grecques menée par le roi spartiate Léonidas à l'armée perse de Xerxès Ier."),
        Question(9175, "Qui a commandé les Grecs aux Thermopyles?", listOf("Périclès", "Thémistocle", "Léonidas", "Miltiade"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le roi spartiate Léonidas Ier commandait les forces grecques lors de la bataille des Thermopyles en 480 av. J.-C., où ils affrontèrent l'armée perse de Xerxès."),
        Question(9176, "En quelle année la Guerre du Péloponnèse a-t-elle commencé?", listOf("431 avant J.C.", "420 avant J.C.", "410 avant J.C.", "400 avant J.C."), 0, "Histoire", Difficulty.HARD, explanation = "La guerre du Péloponnèse, opposant Athènes et Sparte, a débuté en 431 avant J.-C., suite aux tensions croissantes entre les deux cités grecques et leurs alliances respectives."),
        Question(9177, "En quelle année la Guerre du Péloponnèse s'est-elle terminée?", listOf("421 avant J.C.", "411 avant J.C.", "404 avant J.C.", "394 avant J.C."), 2, "Histoire", Difficulty.HARD, explanation = "La guerre du Péloponnèse, opposant Athènes et Sparte, s'achève en 404 avant J.-C. avec la capitulation d'Athènes et la destruction de ses Longs Murs."),
        Question(9178, "Qui a remporté la Guerre du Péloponnèse?", listOf("Athènes", "Sparte", "Thèbes", "Corinthe"), 1, "Histoire", Difficulty.HARD, explanation = "Sparte et sa ligue ont vaincu Athènes et la ligue de Délos en 404 av. J.-C., mettant fin à la guerre du Péloponnèse après des décennies de conflit."),
        Question(9179, "Quel général grec a remporté la victoire pour Sparte?", listOf("Alcibiade", "Lysandre", "Gylippus", "Épaminondas"), 1, "Histoire", Difficulty.HARD, explanation = "Lysandre commanda la flotte spartiate qui vainquit Athènes à Aigos Potamos en 405 av. J.-C., mettant fin à la guerre du Péloponnèse."),
        Question(9180, "En quelle année Sparte a-t-elle dominé la Grèce?", listOf("430 avant J.C.", "400 avant J.C.", "370 avant J.C.", "330 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "Sparte a dominé la Grèce après sa victoire contre Athènes lors de la guerre du Péloponnèse, qui s'est achevée en 404 avant J.C., marquant l'apogée de son hégémonie vers 400 avant J.C."),
        Question(9181, "En quelle année la Bataille de Leuctes s'est-elle déroulée?", listOf("380 avant J.C.", "371 avant J.C.", "360 avant J.C.", "350 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Leuctes en 371 av. J.-C. vit la défaite de Sparte face à Thèbes, dirigée par Épaminondas, brisant ainsi l'hégémonie spartiate en Grèce."),
        Question(9182, "Qui a mené Thèbes à la victoire à la Bataille de Leuctes?", listOf("Pélopidas", "Épaminondas", "Jason de Phères", "Alcibiade"), 1, "Histoire", Difficulty.HARD, explanation = "Épaminondas, général thébain, révolutionna la tactique militaire en utilisant un ordre oblique pour vaincre Sparte à Leuctes en 371 av. J.-C., brisant ainsi sa suprématie."),
        Question(9183, "En quelle année Alexandre le Grand a-t-il conquis l'Empire perse?", listOf("332 avant J.C.", "330 avant J.C.", "328 avant J.C.", "326 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "Alexandre le Grand a conquis l'Empire perse achéménide après sa victoire décisive à la bataille de Gaugamèles en 331 av. J.-C., menant à la chute de Persépolis en 330 av. J.-C."),
        Question(9184, "Quel était le nom du tuteur d'Alexandre le Grand?", listOf("Aristote", "Platon", "Plutarque", "Thucydide"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Aristote fut le précepteur d'Alexandre le Grand à partir de 343 av. J.-C., sur invitation de son père Philippe II de Macédoine."),
        Question(9185, "En quelle année la Bataille de Gaugamèles s'est-elle déroulée?", listOf("332 avant J.C.", "331 avant J.C.", "330 avant J.C.", "328 avant J.C."), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Gaugamèles opposa Alexandre le Grand à Darius III en 331 avant J.-C., marquant la chute de l'Empire perse achéménide."),
        Question(9186, "Qui était Darius III?", listOf("Un général perse", "Un roi perse", "Un satrap", "Un général grec"), 1, "Histoire", Difficulty.HARD, explanation = "Darius III fut le dernier roi de l'Empire achéménide, régnant de 336 à 330 avant J.-C., avant d'être vaincu par Alexandre le Grand."),
        Question(9187, "En quelle année la Bataille de l'Hydaspe s'est-elle déroulée?", listOf("328 avant J.C.", "327 avant J.C.", "326 avant J.C.", "325 avant J.C."), 2, "Histoire", Difficulty.HARD, explanation = "La bataille de l'Hydaspe opposa Alexandre le Grand au roi indien Porus en 326 avant J.-C., marquant la dernière grande conquête d'Alexandre en Inde."),
        Question(9188, "Qui a commandé l'armée indienne à la Bataille de l'Hydaspe?", listOf("Ashoka", "Porus", "Chandragupta", "Duriyodhana"), 1, "Histoire", Difficulty.HARD, explanation = "Porus était le roi indien du royaume de Paurava qui affronta Alexandre le Grand sur les rives de l'Hydaspe en 326 av. J.-C."),
        Question(9189, "En quelle année Alexandre le Grand est-il mort?", listOf("326 avant J.C.", "323 avant J.C.", "320 avant J.C.", "310 avant J.C."), 1, "Histoire", Difficulty.MEDIUM, explanation = "Alexandre le Grand est mort en 323 avant J.-C. à Babylone, probablement des suites d'une maladie ou d'un empoisonnement, à l'âge de 32 ans."),
        Question(9190, "Quel est le plus long règne d'un monarque?", listOf("Louis XIV", "Édouard III", "Georges III", "Victoria"), 0, "Histoire", Difficulty.HARD, explanation = "Louis XIV a régné 72 ans, de 1643 à 1715, ce qui constitue le plus long règne d'un monarque dans l'histoire européenne."),
        Question(9191, "En quelle année Louis XIV a-t-il pris le pouvoir?", listOf("1643", "1654", "1661", "1672"), 2, "Histoire", Difficulty.HARD, explanation = "Louis XIV a pris le pouvoir en 1661 après la mort du cardinal Mazarin, mettant fin à la régence et instaurant son règne personnel sans Premier ministre."),
        Question(9192, "Combien d'années Louis XIV a-t-il régné?", listOf("54", "62", "72", "82"), 2, "Histoire", Difficulty.HARD, explanation = "Louis XIV a régné 72 ans, de 1643 à 1715, ce qui constitue le plus long règne de l'histoire de France."),
        Question(9193, "Quel était le surnom de Louis XIV?", listOf("Le Roi sage", "Le Roi Soleil", "Le Roi guerrier", "Le Roi bâtisseur"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Louis XIV a choisi le soleil comme emblème pour symboliser son pouvoir absolu et sa centralité dans l'État, évoquant l'astre qui éclaire et régit tout."),
        Question(9194, "En quelle année Louis XIV a-t-il commencé la construction de Versailles?", listOf("1661", "1668", "1672", "1680"), 1, "Histoire", Difficulty.HARD, explanation = "Louis XIV transforma le pavillon de chasse de son père en palais à partir de 1668, marquant le début des grands travaux de Versailles qui durèrent plusieurs décennies."),
        Question(9195, "En quelle année la Cour royale a-t-elle déménagé à Versailles?", listOf("1680", "1682", "1685", "1690"), 1, "Histoire", Difficulty.HARD, explanation = "Louis XIV installa définitivement la Cour et le gouvernement à Versailles en 1682, afin de contrôler la noblesse et d'affirmer son pouvoir absolu."),
        Question(9196, "Quel était le ministre des finances de Louis XIV?", listOf("Colbert", "Louvois", "Le Tellier", "Richelieu"), 0, "Histoire", Difficulty.HARD, explanation = "Jean-Baptiste Colbert fut le contrôleur général des finances de Louis XIV de 1665 à 1683, jouant un rôle clé dans le développement du mercantilisme et la modernisation de l'économie française."),
        Question(9197, "En quelle année la Guerre de Succession d'Espagne a-t-elle commencé?", listOf("1700", "1701", "1702", "1703"), 1, "Histoire", Difficulty.HARD, explanation = "La guerre éclata en 1701 après la mort sans héritier de Charles II d'Espagne, provoquant un conflit européen pour le contrôle de son empire."),
        Question(9198, "En quelle année la Guerre de Succession d'Espagne s'est-elle terminée?", listOf("1710", "1711", "1712", "1713"), 3, "Histoire", Difficulty.HARD, explanation = "Le traité d'Utrecht, signé en 1713, mit fin à la Guerre de Succession d'Espagne en reconnaissant Philippe V comme roi d'Espagne tout en lui imposant la renonciation à ses droits sur le trône de France."),
        Question(9199, "Quel traité a mis fin à la Guerre de Succession d'Espagne?", listOf("Traité de Madrid", "Traité d'Utrecht", "Traité de Rastadt", "Traité de Nystad"), 1, "Histoire", Difficulty.HARD, explanation = "Signé en 1713, le Traité d'Utrecht mit fin à la Guerre de Succession d'Espagne en reconnaissant Philippe V comme roi d'Espagne, tout en redistribuant les territoires européens pour maintenir l'équilibre des puissances."),
        Question(9200, "Qui a été le successeur de Louis XIV?", listOf("Louis XV", "Philippe d'Orléans", "Louis le Brun", "Le Regent"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Louis XIV est mort en 1715 après 72 ans de règne. Son arrière-petit-fils, Louis XV, lui a succédé à l'âge de 5 ans, sous la régence de Philippe d'Orléans."),
        Question(9201, "En quelle année Louis XV a-t-il pris le pouvoir?", listOf("1710", "1715", "1720", "1725"), 1, "Histoire", Difficulty.HARD, explanation = "Louis XV devient roi à la mort de son arrière-grand-père Louis XIV en 1715, mais il ne gouverne effectivement qu'à partir de 1723, après la régence de Philippe d'Orléans."),
        Question(9202, "Quel était le surnom de Louis XV?", listOf("Le Bien-Aimé", "Le Sage", "Le Magnifique", "L'Aventureux"), 0, "Histoire", Difficulty.HARD, explanation = "Louis XV reçut ce surnom après sa guérison miraculeuse d'une grave maladie à Metz en 1744, qui suscita un élan de ferveur populaire."),
        Question(9203, "En quelle année la Guerre de Sept Ans a-t-elle commencé?", listOf("1754", "1756", "1758", "1759"), 1, "Histoire", Difficulty.HARD, explanation = "La guerre de Sept Ans, qui opposa la France et l'Autriche à la Prusse et la Grande-Bretagne, débuta officiellement en 1756 après des affrontements coloniaux en Amérique du Nord dès 1754."),
        Question(9204, "En quelle année la Guerre de Sept Ans s'est-elle terminée?", listOf("1760", "1761", "1762", "1763"), 3, "Histoire", Difficulty.HARD, explanation = "Le traité de Paris, signé le 10 février 1763, mit fin à la guerre de Sept Ans entre la France et la Grande-Bretagne, redessinant les colonies nord-américaines."),
        Question(9205, "Quel traité a mis fin à la Guerre de Sept Ans?", listOf("Traité de Hubertusburg", "Traité de Paris", "Traité d'Hubertusbourg", "Les deux A et B"), 3, "Histoire", Difficulty.HARD, explanation = "Le traité de Paris (1763) et le traité d'Hubertsbourg (1763) ont tous deux mis fin à la Guerre de Sept Ans, le premier entre la France, l'Espagne et la Grande-Bretagne, le second entre la Prusse et l'Autriche."),
        Question(9206, "Qui était le principal adversaire de la France pendant la Guerre de Sept Ans?", listOf("La Prusse", "L'Autriche", "La Grande-Bretagne", "La Russie"), 2, "Histoire", Difficulty.HARD, explanation = "La Guerre de Sept Ans (1756-1763) opposa principalement la France et la Grande-Bretagne pour la domination coloniale et maritime."),
        Question(9207, "Quel roi prussien a dominé la Guerre de Sept Ans?", listOf("Frédéric Ier", "Frédéric II", "Frédéric III", "Frédéric IV"), 1, "Histoire", Difficulty.HARD, explanation = "Frédéric II, dit le Grand, a mené la Prusse durant la guerre de Sept Ans (1756-1763), affrontant avec succès une coalition européenne malgré des ressources limitées."),
        Question(9208, "En quelle année Frédéric II a-t-il pris le pouvoir?", listOf("1730", "1740", "1745", "1750"), 1, "Histoire", Difficulty.HARD, explanation = "Frédéric II de Prusse, dit Frédéric le Grand, accède au trône en 1740 à la mort de son père Frédéric-Guillaume Ier."),
        Question(9209, "Quel était le surnom de Frédéric II?", listOf("Frédéric le Sage", "Frédéric le Grand", "Frédéric le Magnifique", "Frédéric le Bâtisseur"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Frédéric II, roi de Prusse de 1740 à 1786, fut surnommé Frédéric le Grand en raison de ses réformes éclairées et de ses victoires militaires, notamment pendant la guerre de Sept Ans."),
        Question(9210, "En quelle année la Révolution française a-t-elle pris fin?", listOf("1793", "1794", "1799", "1804"), 2, "Histoire", Difficulty.HARD, explanation = "La Révolution française s'achève en 1799 avec le coup d'État du 18 Brumaire, qui porte Napoléon Bonaparte au pouvoir et instaure le Consulat."),
        Question(9211, "Quel événement a marqué la fin de la Révolution française?", listOf("L'exécution du roi", "Le Thermidor", "Le Coup d'État de Napoléon", "L'établissement du Consulat"), 2, "Histoire", Difficulty.HARD, explanation = "Le 9 novembre 1799, Napoléon Bonaparte renverse le Directoire par un coup d'État, mettant fin à la Révolution française et instaurant le Consulat."),
        Question(9212, "En quelle année Robespierre a-t-il établi la Terreur?", listOf("1791", "1792", "1793", "1794"), 2, "Histoire", Difficulty.HARD, explanation = "La Terreur est instaurée par le Comité de salut public dirigé par Robespierre en septembre 1793, marquant une période de répression politique intense pendant la Révolution française."),
        Question(9213, "En quelle année le Thermidor s'est-il produit?", listOf("1792", "1793", "1794", "1795"), 2, "Histoire", Difficulty.HARD, explanation = "Le 9 Thermidor an II (27 juillet 1794) marque la chute de Robespierre et la fin de la Terreur, événement clé de la Révolution française."),
        Question(9214, "Qui a renversé Robespierre lors du Thermidor?", listOf("Danton", "Desmoulins", "Tallien", "Fréron"), 2, "Histoire", Difficulty.HARD, explanation = "Tallien, député montagnard, organisa la chute de Robespierre le 9 Thermidor an II (27 juillet 1794) pour mettre fin à la Terreur et sauver sa propre tête."),
        Question(9215, "En quelle année la Constitution de 1795 a-t-elle été adoptée?", listOf("1793", "1794", "1795", "1796"), 2, "Histoire", Difficulty.HARD, explanation = "Adoptée le 22 août 1795, cette Constitution établit le Directoire, un régime qui succède à la Terreur et marque la fin de la Convention nationale."),
        Question(9216, "Quel était le nom du gouvernement établi en 1795?", listOf("Le Directoire", "Le Consulat", "L'Assemblée nationale", "La Convention"), 0, "Histoire", Difficulty.HARD, explanation = "Le Directoire est le régime politique qui a dirigé la France de 1795 à 1799, succédant à la Convention nationale et précédant le Consulat de Napoléon Bonaparte."),
        Question(9217, "En quelle année Napoléon a-t-il renversé le Directoire?", listOf("1797", "1798", "1799", "1800"), 2, "Histoire", Difficulty.HARD, explanation = "Le coup d'État du 18 Brumaire, qui mit fin au Directoire, eut lieu en novembre 1799. Napoléon Bonaparte y instaura le Consulat, dont il devint Premier consul."),
        Question(9218, "Quel coup d'État Napoléon a-t-il organisé?", listOf("Le coup d'État du 18 Brumaire", "Le coup d'État du 9 Thermidor", "Le coup d'État du 14 juillet", "Le coup d'État du 10 août"), 0, "Histoire", Difficulty.HARD, explanation = "Le 18 Brumaire an VIII (9 novembre 1799), Napoléon Bonaparte renverse le Directoire par un coup d'État, instaurant le Consulat dont il devient Premier consul."),
        Question(9219, "En quelle année Napoléon a-t-il établi le Consulat?", listOf("1798", "1799", "1800", "1801"), 1, "Histoire", Difficulty.HARD, explanation = "Le coup d'État du 18 Brumaire an VIII (9 novembre 1799) renversa le Directoire et permit à Napoléon Bonaparte de prendre le pouvoir en instaurant le Consulat, dont il devint Premier consul."),
        Question(9220, "En quelle année Napoléon a-t-il remporté la Bataille de Marengo?", listOf("1798", "1799", "1800", "1801"), 2, "Histoire", Difficulty.HARD, explanation = "Cette bataille décisive de la deuxième campagne d'Italie eut lieu le 14 juin 1800 et permit à Napoléon de consolider son pouvoir après son retour d'Égypte."),
        Question(9221, "En quelle année la Bataille de Austerlitz s'est-elle déroulée?", listOf("1804", "1805", "1806", "1807"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille d'Austerlitz, aussi appelée bataille des Trois Empereurs, a eu lieu le 2 décembre 1805 et oppose la Grande Armée de Napoléon Ier aux armées russe et autrichienne."),
        Question(9222, "En quelle année la Bataille de Iéna s'est-elle déroulée?", listOf("1804", "1805", "1806", "1807"), 2, "Histoire", Difficulty.HARD, explanation = "La bataille de Iéna a eu lieu le 14 octobre 1806, opposant la Grande Armée de Napoléon Ier aux forces prussiennes, et se soldant par une victoire française décisive."),
        Question(9223, "En quelle année la Bataille d'Eylau s'est-elle déroulée?", listOf("1805", "1806", "1807", "1808"), 2, "Histoire", Difficulty.HARD, explanation = "La bataille d'Eylau opposa la Grande Armée de Napoléon Ier aux forces russo-prussiennes en Prusse-Orientale, et se déroula les 7 et 8 février 1807."),
        Question(9224, "En quelle année le Traité de Tilsit a-t-il été signé?", listOf("1805", "1806", "1807", "1808"), 2, "Histoire", Difficulty.HARD, explanation = "Le Traité de Tilsit fut signé en 1807 entre Napoléon Ier et le tsar Alexandre Ier, mettant fin à la guerre de la Quatrième Coalition."),
        Question(9225, "En quelle année le Blocus continental a-t-il été établi?", listOf("1805", "1806", "1807", "1808"), 2, "Histoire", Difficulty.HARD, explanation = "Napoléon Ier instaure le Blocus continental par le décret de Berlin le 21 novembre 1806, mais il est effectivement mis en œuvre à partir de 1807."),
        Question(9226, "En quelle année la Campagne d'Égypte a-t-elle commencé?", listOf("1796", "1797", "1798", "1799"), 2, "Histoire", Difficulty.HARD, explanation = "La campagne d'Égypte est une expédition militaire menée par Napoléon Bonaparte à partir de 1798, visant à menacer les intérêts britanniques en Orient."),
        Question(9227, "En quelle année Napoléon a-t-il envahi l'Espagne?", listOf("1806", "1807", "1808", "1809"), 2, "Histoire", Difficulty.HARD, explanation = "Napoléon envahit l'Espagne en 1808 sous prétexte de renforcer le blocus continental contre le Royaume-Uni, ce qui déclencha la guerre d'indépendance espagnole."),
        Question(9228, "En quelle année la Guerre de la Péninsule a-t-elle commencé?", listOf("1806", "1807", "1808", "1809"), 2, "Histoire", Difficulty.HARD, explanation = "La Guerre de la Péninsule a débuté en 1808 lorsque Napoléon a envahi l'Espagne et le Portugal, déclenchant un conflit majeur de la guerre d'indépendance espagnole."),
        Question(9229, "En quelle année Napoléon a-t-elle envahi la Russie?", listOf("1810", "1811", "1812", "1813"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La Grande Armée de Napoléon a envahi la Russie en juin 1812, marquant le début de la campagne de Russie qui s'est soldée par une retraite désastreuse."),
        Question(9230, "En quelle année la Grande Armée a-t-elle été vaincue en Russie?", listOf("1811", "1812", "1813", "1814"), 1, "Histoire", Difficulty.HARD, explanation = "La Grande Armée de Napoléon a subi une défaite catastrophique lors de la campagne de Russie en 1812, marquée par la retraite meurtrière de l'hiver russe."),
        Question(9231, "Quel événement a marqué le début de la fin pour Napoléon?", listOf("La Campagne de Russie", "Le Traité de Tilsit", "La Guerre de la Péninsule", "La Bataille de Waterloo"), 0, "Histoire", Difficulty.HARD, explanation = "La campagne de Russie en 1812 fut un désastre militaire pour Napoléon, avec la perte de la Grande Armée, ce qui affaiblit son empire et encouragea ses ennemis à se coaliser contre lui."),
        Question(9232, "En quelle année les Alliés ont-ils envahi la France?", listOf("1812", "1813", "1814", "1815"), 2, "Histoire", Difficulty.HARD, explanation = "En 1814, les armées alliées (Prusse, Autriche, Russie, Royaume-Uni) envahissent la France pour renverser Napoléon Ier, menant à son abdication en avril."),
        Question(9233, "En quelle année Napoléon a-t-il abdiqué pour la première fois?", listOf("1813", "1814", "1815", "1816"), 1, "Histoire", Difficulty.HARD, explanation = "Après la défaite de la campagne de France et l’entrée des coalisés à Paris, Napoléon abdique sans condition le 6 avril 1814."),
        Question(9234, "En quelle année Napoléon a-t-il échappé de l'île d'Elbe?", listOf("1814", "1815", "1816", "1817"), 1, "Histoire", Difficulty.HARD, explanation = "Napoléon s'est évadé de l'île d'Elbe le 26 février 1815, entamant les Cent-Jours qui ont mené à la bataille de Waterloo."),
        Question(9235, "Quel était le nom de la période des 100 jours?", listOf("Les 100 jours de Napoléon", "Le retour de Napoléon", "Le Second Empire", "L'Époque des Cent-Jours"), 0, "Histoire", Difficulty.HARD, explanation = "Napoléon Bonaparte revint au pouvoir en France en mars 1815 après son exil sur l'île d'Elbe, mais fut définitivement vaincu à Waterloo en juin, marquant cette courte période de cent jours."),
        Question(9236, "En quelle année Napoléon a-t-il abdiqué définitivement?", listOf("1814", "1815", "1816", "1817"), 1, "Histoire", Difficulty.HARD, explanation = "Napoléon abdique définitivement le 22 juin 1815, après sa défaite à Waterloo, mettant fin à l'Empire des Cent-Jours."),
        Question(9237, "En quelle année Napoléon est-il mort?", listOf("1820", "1821", "1822", "1823"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Napoléon Bonaparte est mort le 5 mai 1821 sur l'île de Sainte-Hélène, où il était exilé par les Britanniques depuis 1815."),
        Question(9238, "Quel était le siège de l'exil final de Napoléon?", listOf("L'île d'Elbe", "Sainte-Hélène", "Corse", "Malta"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Après sa défaite à Waterloo en 1815, les Britanniques l'ont exilé sur cette île isolée de l'Atlantique Sud pour empêcher toute évasion. Il y est mort en 1821."),
        Question(9239, "En quelle année Louis XVIII a-t-il été restauré au trône?", listOf("1813", "1814", "1815", "1816"), 1, "Histoire", Difficulty.HARD, explanation = "Louis XVIII a été restauré au trône en 1814 après la première abdication de Napoléon Ier, marquant le début de la Première Restauration."),
        Question(9240, "Quel était le nom du congrès qui a réorganisé l'Europe après la chute de Napoléon?", listOf("Congrès de Paris", "Congrès de Vienne", "Congrès d'Aix-la-Chapelle", "Congrès de Berlin"), 1, "Histoire", Difficulty.HARD, explanation = "Le Congrès de Vienne, tenu de 1814 à 1815, a redessiné les frontières européennes et rétabli l'équilibre des puissances après les guerres napoléoniennes."),
        Question(9241, "En quelle année le Congrès de Vienne s'est-il terminé?", listOf("1814", "1815", "1816", "1817"), 1, "Histoire", Difficulty.HARD, explanation = "Le Congrès de Vienne, qui a redessiné la carte de l'Europe après les guerres napoléoniennes, s'est achevé en juin 1815, juste avant la défaite définitive de Napoléon à Waterloo."),
        Question(9242, "Qui a présidé le Congrès de Vienne?", listOf("Castlereagh", "Metternich", "Talleyrand", "Bismarck"), 1, "Histoire", Difficulty.HARD, explanation = "Le chancelier autrichien Metternich a présidé le Congrès de Vienne en 1814-1815, jouant un rôle central dans la réorganisation de l'Europe après les guerres napoléoniennes."),
        Question(9243, "En quelle année la Sainte-Alliance a-t-elle été créée?", listOf("1814", "1815", "1816", "1817"), 1, "Histoire", Difficulty.HARD, explanation = "La Sainte-Alliance fut créée en 1815, après la défaite de Napoléon, par les monarques de Russie, d'Autriche et de Prusse pour défendre l'ordre monarchique en Europe."),
        Question(9244, "Qui a créé la Sainte-Alliance?", listOf("François Ier", "Alexandre Ier", "Frédéric II", "Napoléon"), 1, "Histoire", Difficulty.HARD, explanation = "Alexandre Ier, tsar de Russie, proposa la Sainte-Alliance en 1815 après la défaite de Napoléon, un pacte entre monarques européens pour défendre les principes chrétiens et l'ordre conservateur."),
        Question(9245, "En quelle année la Révolution de 1848 a-t-elle commencé?", listOf("1846", "1847", "1848", "1849"), 2, "Histoire", Difficulty.HARD, explanation = "Cette révolution, qui débuta en février 1848, mit fin à la monarchie de Juillet et instaura la Deuxième République en France."),
        Question(9246, "Quel événement a déclenché la Révolution de 1848?", listOf("La crise économique", "L'effondrement financier", "La famine des pommes de terre", "Les réformes politiques"), 2, "Histoire", Difficulty.HARD, explanation = "La famine de la pomme de terre en Europe, notamment en Irlande et en France, a provoqué une grave crise alimentaire et économique, exacerbant les tensions sociales et politiques qui ont conduit à la Révolution de 1848."),
        Question(9247, "En quelle année Louis-Philippe a-t-il abdiqué?", listOf("1846", "1847", "1848", "1849"), 2, "Histoire", Difficulty.HARD, explanation = "Louis-Philippe abdique le 24 février 1848, marquant la fin de la monarchie de Juillet et ouvrant la voie à la Deuxième République française."),
        Question(9248, "Quel était le nom du gouvernement établi après la Révolution de 1848?", listOf("La Deuxième République", "Le Second Empire", "La Troisième République", "La Première République"), 0, "Histoire", Difficulty.HARD, explanation = "La Révolution de 1848 mit fin à la monarchie de Juillet, conduisant à la proclamation de la Deuxième République en France."),
        Question(9249, "En quelle année la Seconde République s'est-elle terminée?", listOf("1850", "1851", "1852", "1853"), 2, "Histoire", Difficulty.HARD, explanation = "La Seconde République française prit fin en 1852 lorsque Louis-Napoléon Bonaparte, après son coup d'État de 1851, rétablit l'Empire par un plébiscite et devint Napoléon III."),
        Question(9250, "Qui a établi le Second Empire?", listOf("Napoléon III", "Napoléon Bonaparte", "Louis-Napoléon", "Victor Hugo"), 0, "Histoire", Difficulty.HARD, explanation = "Napoléon III, neveu de Napoléon Ier, proclame le Second Empire le 2 décembre 1852 après un coup d'État en 1851 et un plébiscite favorable."),
        Question(9251, "En quelle année le Second Empire a-t-il été établi?", listOf("1850", "1851", "1852", "1853"), 2, "Histoire", Difficulty.HARD, explanation = "Louis-Napoléon Bonaparte, neveu de Napoléon Ier, proclame le Second Empire le 2 décembre 1852, un an après son coup d'État."),
        Question(9252, "En quelle année le Second Empire s'est-il terminé?", listOf("1868", "1869", "1870", "1871"), 2, "Histoire", Difficulty.HARD, explanation = "Le Second Empire s'est terminé le 4 septembre 1870, après la défaite de Sedan face à la Prusse et la capture de Napoléon III."),
        Question(9253, "Quel événement a marqué la fin du Second Empire?", listOf("La Guerre franco-prussienne", "La Commode", "La Révolution", "L'exil de Napoléon"), 0, "Histoire", Difficulty.HARD, explanation = "La défaite de Napoléon III à Sedan en 1870 face aux Prussiens entraîne sa capture et l'effondrement du régime, proclamant la Troisième République."),
        Question(9254, "En quelle année la Guerre franco-prussienne a-t-elle commencé?", listOf("1868", "1869", "1870", "1871"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La guerre franco-prussienne débute en 1870, lorsque Napoléon III déclare la guerre à la Prusse après la dépêche d'Ems."),
        Question(9255, "En quelle année la Guerre franco-prussienne s'est-elle terminée?", listOf("1870", "1871", "1872", "1873"), 1, "Histoire", Difficulty.HARD, explanation = "Le traité de Francfort, signé le 10 mai 1871, a officiellement mis fin à la guerre franco-prussienne, entamée en juillet 1870. Cette défaite française a conduit à la perte de l'Alsace-Moselle et à la chute du Second Empire."),
        Question(9256, "Qui a vaincu la France dans la Guerre franco-prussienne?", listOf("L'Allemagne", "La Prusse", "Bismarck", "Tous les trois"), 3, "Histoire", Difficulty.MEDIUM, explanation = "La guerre franco-prussienne de 1870-1871 a opposé la France à une coalition d'États allemands menée par la Prusse, incluant également la Bavière et le Bade."),
        Question(9257, "Quel traité a mis fin à la Guerre franco-prussienne?", listOf("Traité de Frankfurt", "Traité de Francfort", "Traité de Paris", "Traité de Bismarck"), 1, "Histoire", Difficulty.HARD, explanation = "Le Traité de Francfort, signé le 10 mai 1871, a officiellement mis fin à la Guerre franco-prussienne, imposant à la France la perte de l'Alsace-Lorraine et le paiement d'une lourde indemnité."),
        Question(9258, "En quelle année la Commune de Paris a-t-elle été établie?", listOf("1870", "1871", "1872", "1873"), 1, "Histoire", Difficulty.HARD, explanation = "La Commune de Paris fut proclamée le 18 mars 1871 après la défaite de la France face à la Prusse et le soulèvement des Parisiens contre le gouvernement provisoire."),
        Question(9259, "En quelle année la Commune de Paris a-t-elle été écrasée?", listOf("1871", "1872", "1873", "1874"), 0, "Histoire", Difficulty.HARD, explanation = "La Commune de Paris a été écrasée lors de la Semaine sanglante, du 21 au 28 mai 1871, par les troupes versaillaises."),
        Question(9260, "Qui a établi la Troisième République en France?", listOf("Adolphe Thiers", "Jules Grévy", "Léon Gambetta", "Patrice de MacMahon"), 2, "Histoire", Difficulty.HARD, explanation = "Léon Gambetta proclame la Troisième République le 4 septembre 1870 après la défaite de Sedan et la chute de Napoléon III."),
        Question(9261, "En quelle année la Troisième République a-t-elle été établie?", listOf("1870", "1871", "1872", "1873"), 1, "Histoire", Difficulty.HARD, explanation = "La Troisième République a été proclamée le 4 septembre 1870 après la chute du Second Empire, mais elle n'a été définitivement établie qu'en 1871 après la défaite française face à la Prusse et la Commune de Paris."),
        Question(9262, "Qui a unifié l'Allemagne?", listOf("Frédéric II", "Guillaume Ier", "Otto von Bismarck", "Léopold Ier"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Otto von Bismarck, en tant que chancelier prussien, a orchestré l'unification allemande par une série de guerres victorieuses entre 1864 et 1871."),
        Question(9263, "En quelle année l'Allemagne s'est-elle unifiée?", listOf("1868", "1869", "1870", "1871"), 3, "Histoire", Difficulty.HARD, explanation = "L'unification allemande a été proclamée le 18 janvier 1871 dans la galerie des Glaces du château de Versailles, après la victoire de la Prusse sur la France lors de la guerre franco-prussienne."),
        Question(9264, "Quel événement a marqué l'unification de l'Allemagne?", listOf("La Bataille de Sedan", "La Proclamation de l'Empereur", "Le Traité de Francfort", "La Bataille de Königgrätz"), 1, "Histoire", Difficulty.HARD, explanation = "La Proclamation de l'Empereur, le 18 janvier 1871 dans la galerie des Glaces à Versailles, a officialisé l'unification des États allemands sous la direction de la Prusse et du roi Guillaume Ier."),
        Question(9265, "En quelle année l'Italie s'est-elle unifiée?", listOf("1859", "1860", "1861", "1870"), 2, "Histoire", Difficulty.HARD, explanation = "Le processus du Risorgimento a abouti à la proclamation du royaume d'Italie en 1861, avec Victor-Emmanuel II comme roi."),
        Question(9266, "Qui a unifié l'Italie?", listOf("Camillo Cavour", "Giuseppe Garibaldi", "Victor-Emmanuel II", "Tous les trois"), 3, "Histoire", Difficulty.MEDIUM, explanation = "Garibaldi, Cavour et Victor-Emmanuel II ont chacun joué un rôle clé dans l'unification italienne au XIXe siècle, par des actions militaires, diplomatiques et politiques."),
        Question(9267, "En quelle année Cavour a-t-il commencé l'unification italienne?", listOf("1855", "1858", "1859", "1860"), 2, "Histoire", Difficulty.HARD, explanation = "Camillo Cavour, alors Premier ministre du royaume de Sardaigne, engagea le processus d'unification italienne en 1859 en signant les accords de Plombières avec la France et en déclenchant la deuxième guerre d'indépendance italienne contre l'Autriche."),
        Question(9268, "En quelle année Garibaldi a-t-il débarqué en Sicile?", listOf("1858", "1859", "1860", "1861"), 2, "Histoire", Difficulty.HARD, explanation = "L'expédition des Mille, menée par Garibaldi, débarqua à Marsala en Sicile le 11 mai 1860, marquant le début de la campagne qui permit l'unification de l'Italie."),
        Question(9269, "Quel était le nom de l'expédition de Garibaldi?", listOf("L'expédition des Mille", "L'expédition des Chevaliers", "L'expédition du Risorgimento", "L'expédition de la Liberté"), 0, "Histoire", Difficulty.HARD, explanation = "L'expédition des Mille, menée par Garibaldi en 1860, visait à conquérir le royaume des Deux-Siciles pour unifier l'Italie."),
        Question(9270, "En quelle année Rome a-t-elle été annexée à l'Italie?", listOf("1860", "1867", "1869", "1870"), 3, "Histoire", Difficulty.HARD, explanation = "L'annexion de Rome à l'Italie eut lieu en 1870, lorsque les troupes italiennes entrèrent dans la ville, mettant fin au pouvoir temporel des papes."),
        Question(9271, "Quel événement a marqué la fin du pouvoir temporal du Pape?", listOf("L'annexion de Rome", "La Révolution de 1848", "La Guerre franco-prussienne", "L'unification italienne"), 0, "Histoire", Difficulty.HARD, explanation = "L'annexion de Rome par le royaume d'Italie en 1870 a mis fin aux États pontificaux, supprimant le pouvoir temporel du pape sur un territoire."),
        Question(9272, "En quelle année l'Afrique a-t-elle été colonisée par les Européens?", listOf("1850", "1880", "1890", "1900"), 1, "Histoire", Difficulty.HARD, explanation = "La colonisation européenne de l'Afrique s'est intensifiée à partir de 1880, marquant le début du \"partage de l'Afrique\" lors de la conférence de Berlin (1884-1885)."),
        Question(9273, "En quelle année la Conférence de Berlin a-t-elle eu lieu?", listOf("1882", "1883", "1884", "1885"), 3, "Histoire", Difficulty.HARD, explanation = "La Conférence de Berlin, qui s'est tenue de novembre 1884 à février 1885, a organisé le partage de l'Afrique entre les puissances européennes."),
        Question(9274, "Qui a présidé la Conférence de Berlin?", listOf("Léopold II", "Otto von Bismarck", "Jules Ferry", "Stanley"), 1, "Histoire", Difficulty.HARD, explanation = "La Conférence de Berlin (1884-1885) sur le partage de l'Afrique fut organisée et présidée par le chancelier allemand Otto von Bismarck."),
        Question(9275, "Quel était l'objectif de la Conférence de Berlin?", listOf("Coloniser l'Afrique", "Diviser l'Afrique", "Établir les règles du commerce africain", "Tous les trois"), 1, "Histoire", Difficulty.HARD, explanation = "La conférence de Berlin (1884-1885) a fixé les règles du partage colonial de l'Afrique entre les puissances européennes, sans consulter les populations locales."),
        Question(9276, "Quel roi belge a contrôlé le Congo?", listOf("Léopold Ier", "Léopold II", "Léopold III", "Albert Ier"), 1, "Histoire", Difficulty.HARD, explanation = "Léopold II a dirigé l'État indépendant du Congo de 1885 à 1908, une période marquée par l'exploitation des ressources et des violences contre la population locale."),
        Question(9277, "En quelle année la Reine Victoria a-t-elle accédé au trône?", listOf("1835", "1837", "1840", "1845"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Victoria monta sur le trône britannique en 1837 à l'âge de 18 ans, après la mort de son oncle, le roi Guillaume IV."),
        Question(9278, "Combien d'années Victoria a-t-elle régné?", listOf("50", "60", "64", "70"), 2, "Histoire", Difficulty.HARD, explanation = "Le règne de la reine Victoria a duré de 1837 à 1901, soit 63 ans et sept mois, ce qui est souvent arrondi à 64 ans."),
        Question(9279, "Quel était le surnom de l'époque du règne de Victoria?", listOf("L'époque géorgienne", "L'époque victorienne", "L'époque édouardienne", "L'époque georgienne"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Victoria a régné sur le Royaume-Uni de 1837 à 1901, une période marquée par l'expansion industrielle et culturelle, d'où le nom d'époque victorienne donné à son règne."),
        Question(9280, "En quelle année Albert a-t-il épousé Victoria?", listOf("1835", "1837", "1839", "1840"), 3, "Histoire", Difficulty.HARD, explanation = "Le mariage de la reine Victoria et du prince Albert a eu lieu le 10 février 1840, après des fiançailles officialisées en octobre 1839."),
        Question(9281, "En quelle année Albert est-il mort?", listOf("1859", "1860", "1861", "1862"), 2, "Histoire", Difficulty.HARD, explanation = "Albert, prince consort du Royaume-Uni et époux de la reine Victoria, est mort en 1861 des suites d'une fièvre typhoïde."),
        Question(9282, "Quel était le monument construit en l'honneur d'Albert?", listOf("Le Palais de Crystal", "Le Albert Memorial", "L'Abbaye de Westminster", "Big Ben"), 1, "Histoire", Difficulty.HARD, explanation = "Le Albert Memorial est un monument situé à Londres, érigé à la mémoire du prince Albert, époux de la reine Victoria, après sa mort en 1861."),
        Question(9283, "En quelle année l'Exposition universelle de 1851 a-t-elle eu lieu?", listOf("1849", "1850", "1851", "1852"), 2, "Histoire", Difficulty.HARD, explanation = "L'Exposition universelle de 1851 s'est tenue à Londres, au Crystal Palace, et a été la première exposition internationale des produits de l'industrie."),
        Question(9284, "Où l'Exposition universelle de 1851 a-t-elle eu lieu?", listOf("Paris", "Londres", "Amsterdam", "Berlin"), 1, "Histoire", Difficulty.HARD, explanation = "La Grande Exposition de 1851 s'est tenue à Hyde Park à Londres, dans le célèbre Crystal Palace, un bâtiment innovant en verre et en fer."),
        Question(9285, "Quel était le bâtiment principal de l'Exposition de 1851?", listOf("Le Palais des Machines", "Le Palais de Crystal", "La Tour Eiffel", "Le Palais de l'Industrie"), 1, "Histoire", Difficulty.HARD, explanation = "Le Palais de Cristal, immense structure de verre et de fer, fut construit à Hyde Park pour accueillir la Grande Exposition de 1851, symbole de l'innovation industrielle britannique."),
        Question(9286, "En quelle année la Reine Victoria a-t-elle été proclamée Impératrice?", listOf("1872", "1875", "1876", "1877"), 2, "Histoire", Difficulty.HARD, explanation = "Victoria fut proclamée impératrice des Indes en 1876 sur proposition du Premier ministre Disraeli, renforçant les liens entre la couronne britannique et son empire colonial indien."),
        Question(9287, "En quelle année Disraeli a-t-il proclamé Victoria Impératrice?", listOf("1872", "1875", "1876", "1877"), 2, "Histoire", Difficulty.HARD, explanation = "En 1876, le Premier ministre britannique Benjamin Disraeli fit adopter le Royal Titles Act, qui ajouta le titre d'Impératrice des Indes à la reine Victoria, renforçant ainsi les liens entre la couronne britannique et l'empire colonial indien."),
        Question(9288, "En quelle année la Reine Victoria est-elle morte?", listOf("1899", "1900", "1901", "1902"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La reine Victoria est morte le 22 janvier 1901, après un règne de 63 ans, le plus long de l'histoire britannique à l'époque."),
        Question(9289, "Qui a succédé à Victoria?", listOf("Georges V", "Édouard VII", "Georges VI", "Édouard VIII"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Victoria, reine du Royaume-Uni, est décédée en 1901 après 63 ans de règne. Son fils aîné lui a succédé sous le nom d'Édouard VII."),
        Question(9290, "En quelle année Édouard VII a-t-il accédé au trône?", listOf("1899", "1900", "1901", "1902"), 2, "Histoire", Difficulty.HARD, explanation = "Édouard VII succède à sa mère, la reine Victoria, morte le 22 janvier 1901, après un long règne de 63 ans. Il devient roi à l'âge de 59 ans."),
        Question(9291, "En quelle année l'Alliance franco-russe a-t-elle été formée?", listOf("1891", "1892", "1893", "1894"), 3, "Histoire", Difficulty.HARD, explanation = "L'Alliance franco-russe a été officialisée par une convention militaire secrète en 1894, mettant fin à l'isolement diplomatique de la France et créant un contrepoids à la Triple Alliance."),
        Question(9292, "En quelle année l'Entente cordiale a-t-elle été signée?", listOf("1902", "1904", "1906", "1908"), 1, "Histoire", Difficulty.HARD, explanation = "L'Entente cordiale, signée le 8 avril 1904, mit fin aux rivalités coloniales entre la France et le Royaume-Uni, posant les bases de leur alliance future lors des deux guerres mondiales."),
        Question(9293, "En quelle année l'Accord anglo-russe a-t-il été signé?", listOf("1904", "1905", "1906", "1907"), 3, "Histoire", Difficulty.HARD, explanation = "Signé en 1907, cet accord mit fin aux rivalités coloniales entre la Russie et le Royaume-Uni en Asie, notamment en Perse, en Afghanistan et au Tibet, et contribua à la formation de la Triple-Entente."),
        Question(9294, "En quelle année la Triple Alliance a-t-elle été formée?", listOf("1880", "1882", "1884", "1886"), 1, "Histoire", Difficulty.HARD, explanation = "La Triple Alliance, liant l'Allemagne, l'Autriche-Hongrie et l'Italie, a été signée en 1882 pour contrer l'influence de la France et de la Russie."),
        Question(9295, "Quels pays formaient la Triple Alliance?", listOf("France, Russie, Grande-Bretagne", "Allemagne, Autriche-Hongrie, Italie", "Allemagne, Prusse, Saxe", "France, Belgique, Hollande"), 1, "Histoire", Difficulty.HARD, explanation = "La Triple Alliance, signée en 1882, était un pacte militaire défensif entre l'Allemagne, l'Autriche-Hongrie et l'Italie, visant à isoler la France et à maintenir l'équilibre des puissances en Europe."),
        Question(9296, "En quelle année la Crise marocaine a-t-elle commencé?", listOf("1903", "1904", "1905", "1906"), 2, "Histoire", Difficulty.HARD, explanation = "La première crise marocaine a débuté en 1905 suite à la visite de l'empereur allemand Guillaume II à Tanger, contestant l'influence française au Maroc."),
        Question(9297, "En quelle année la Crise bosniaque a-t-elle eu lieu?", listOf("1905", "1906", "1907", "1908"), 3, "Histoire", Difficulty.HARD, explanation = "La Crise bosniaque de 1908 a éclaté après l'annexion officielle de la Bosnie-Herzégovine par l'Autriche-Hongrie, violant le traité de Berlin de 1878 et provoquant des tensions avec la Serbie et la Russie."),
        Question(9298, "En quelle année la Guerre russo-japonaise a-t-elle commencé?", listOf("1902", "1903", "1904", "1905"), 2, "Histoire", Difficulty.HARD, explanation = "Le conflit éclata en 1904, opposant l'Empire russe et l'Empire du Japon pour le contrôle de la Mandchourie et de la Corée."),
        Question(9299, "En quelle année la Guerre russo-japonaise s'est-elle terminée?", listOf("1904", "1905", "1906", "1907"), 1, "Histoire", Difficulty.HARD, explanation = "La guerre russo-japonaise s'est achevée en 1905 avec la signature du traité de Portsmouth, négocié par les États-Unis. Le Japon en sortit vainqueur, marquant la première défaite d'une puissance européenne face à une nation asiatique à l'époque moderne."),
        Question(9300, "Qui a remporté la Guerre russo-japonaise?", listOf("La Russie", "Le Japon", "L'Allemagne", "La France"), 1, "Histoire", Difficulty.HARD, explanation = "Le conflit de 1904-1905 opposa l'Empire russe et l'Empire japonais pour le contrôle de la Mandchourie et de la Corée. Le Japon remporta une victoire décisive, marquant la première défaite d'une puissance européenne face à une nation asiatique à l'époque moderne."),
        Question(9301, "En quelle année la Révolution russe de 1905 a-t-elle eu lieu?", listOf("1903", "1904", "1905", "1906"), 2, "Histoire", Difficulty.HARD, explanation = "La révolution de 1905 tire son nom de l'année où elle s'est déroulée, marquée par des grèves et des soulèvements contre le régime tsariste."),
        Question(9302, "Quel était l'événement déclencheur de la Révolution de 1905?", listOf("L'Incident du Dimanche rouge", "La Famine", "La Défaite au Japon", "L'Assassinat du Tsar"), 0, "Histoire", Difficulty.HARD, explanation = "Le Dimanche rouge du 9 janvier 1905, où l'armée impériale a tiré sur une manifestation pacifique d'ouvriers à Saint-Pétersbourg, a brisé la confiance populaire envers le tsar et déclenché une vague de grèves et de révoltes."),
        Question(9303, "En quelle année le Manifeste d'octobre a-t-il été publié?", listOf("1903", "1904", "1905", "1906"), 2, "Histoire", Difficulty.HARD, explanation = "Le Manifeste d'octobre a été publié en 1905 par le tsar Nicolas II, sous la pression de la révolution russe de 1905, promettant des libertés civiles et la création d'une Douma."),
        Question(9304, "Qui a publié le Manifeste d'octobre?", listOf("Lénine", "Trotski", "Nicolas II", "Witte"), 3, "Histoire", Difficulty.HARD, explanation = "Le Manifeste d'octobre, promulgué en 1905 sous la pression de la révolution russe, fut rédigé et publié par le comte Serge Witte, alors président du Conseil des ministres de l'Empire russe."),
        Question(9305, "En quelle année la Douma a-t-elle été établie?", listOf("1904", "1905", "1906", "1907"), 2, "Histoire", Difficulty.HARD, explanation = "La Douma d'État a été créée en 1906 suite à la Révolution russe de 1905, lorsque le tsar Nicolas II a accepté de former un parlement élu pour apaiser les troubles politiques."),
        Question(9306, "Qui était le tsar de Russie en 1905?", listOf("Alexandre III", "Nicolas II", "Nicolas Ier", "Paul Ier"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Nicolas II était le tsar de Russie en 1905, année marquée par la révolution russe et le Dimanche rouge."),
        Question(9307, "En quelle année Nicolas II a-t-il accédé au trône?", listOf("1890", "1894", "1898", "1900"), 1, "Histoire", Difficulty.HARD, explanation = "Nicolas II devient tsar de Russie en 1894, après la mort de son père Alexandre III. Son règne s'achève avec son abdication en 1917, durant la révolution russe."),
        Question(9308, "En quelle année la Première Guerre mondiale s'est-elle déroulée?", listOf("1914-1917", "1914-1918", "1914-1919", "1914-1920"), 1, "Histoire", Difficulty.EASY, explanation = "Le conflit débuta en juillet 1914 avec l'invasion de la Serbie par l'Autriche-Hongrie et s'acheva le 11 novembre 1918 par l'armistice signé à Rethondes."),
        Question(9309, "Quel était le casus belli de la Première Guerre mondiale?", listOf("L'invasion de la Belgique", "L'assassinat de François-Ferdinand", "La crise marocaine", "La Bosnie"), 1, "Histoire", Difficulty.MEDIUM, explanation = "L'assassinat de l'archiduc François-Ferdinand, héritier du trône austro-hongrois, par un nationaliste serbe à Sarajevo le 28 juin 1914 a déclenché une crise diplomatique menant à la guerre."),
        Question(9310, "En quelle année les États-Unis ont-ils rejoint la Première Guerre mondiale?", listOf("1915", "1916", "1917", "1918"), 2, "Histoire", Difficulty.EASY, explanation = "Les États-Unis ont déclaré la guerre à l'Allemagne en avril 1917, après le torpillage de navires américains et la découverte du télégramme Zimmermann."),
        Question(9311, "En quelle année la Bataille de la Somme s'est-elle déroulée?", listOf("1915", "1916", "1917", "1918"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de la Somme, l'une des plus meurtrières de la Première Guerre mondiale, a eu lieu en 1916, principalement entre forces britanniques et allemandes."),
        Question(9312, "En quelle année la Bataille de Verdun s'est-elle déroulée?", listOf("1915", "1916", "1917", "1918"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Verdun, l'une des plus longues et meurtrières de la Première Guerre mondiale, a opposé les armées française et allemande de février à décembre 1916."),
        Question(9313, "Qui a commandé les troupes allemandes à Verdun?", listOf("Hindenburg", "Falkenhayn", "Mackensen", "Bellow"), 1, "Histoire", Difficulty.HARD, explanation = "Erich von Falkenhayn, chef d’état-major général de l’armée allemande, planifia l’offensive de Verdun en 1916 pour saigner l’armée française."),
        Question(9314, "Qui a commandé les troupes françaises à Verdun?", listOf("Joffre", "Pétain", "Foch", "Nivelle"), 1, "Histoire", Difficulty.HARD, explanation = "Le général Philippe Pétain a pris le commandement des troupes françaises lors de la bataille de Verdun en 1916, où il a organisé la défense et la logistique pour résister à l'offensive allemande."),
        Question(9315, "En quelle année la Révolution de février a-t-elle eu lieu en Russie?", listOf("1916", "1917", "1918", "1919"), 1, "Histoire", Difficulty.HARD, explanation = "La Révolution de février 1917 a mis fin au tsarisme en Russie, provoquant l'abdication de Nicolas II et l'établissement d'un gouvernement provisoire."),
        Question(9316, "En quelle année la Révolution d'octobre a-t-elle eu lieu en Russie?", listOf("1916", "1917", "1918", "1919"), 1, "Histoire", Difficulty.EASY, explanation = "La Révolution d'octobre a eu lieu en 1917, selon le calendrier julien alors en vigueur en Russie, correspondant au 7 novembre du calendrier grégorien."),
        Question(9317, "Qui a mené la Révolution d'octobre?", listOf("Trotski", "Lénine", "Staline", "Kerenski"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Lénine a dirigé les Bolcheviks lors de la prise du pouvoir en Russie en octobre 1917, renversant le gouvernement provisoire."),
        Question(9318, "En quelle année le Traité de Brest-Litovsk a-t-il été signé?", listOf("1917", "1918", "1919", "1920"), 1, "Histoire", Difficulty.HARD, explanation = "Ce traité, signé le 3 mars 1918, met fin à la participation de la Russie soviétique à la Première Guerre mondiale face aux puissances centrales."),
        Question(9319, "En quelle année la Première Guerre mondiale s'est-elle terminée?", listOf("1917", "1918", "1919", "1920"), 1, "Histoire", Difficulty.EASY, explanation = "L'armistice mettant fin aux combats de la Première Guerre mondiale a été signé le 11 novembre 1918, dans un wagon-restaurant à Rethondes."),
        Question(9320, "Quel événement a marqué la fin de la Première Guerre mondiale?", listOf("L'armistice du 11 novembre", "Le Traité de Versailles", "La Révolution russe", "La signature du Traité de Brest-Litovsk"), 0, "Histoire", Difficulty.HARD, explanation = "Signé le 11 novembre 1918 à Rethondes, cet armistice met fin aux combats entre les Alliés et l'Allemagne, aboutissant à la capitulation de cette dernière et à la cessation des hostilités sur le front occidental."),
        Question(9321, "En quelle année le Traité de Versailles a-t-il été signé?", listOf("1918", "1919", "1920", "1921"), 1, "Histoire", Difficulty.EASY, explanation = "Le Traité de Versailles, qui mit officiellement fin à la Première Guerre mondiale, fut signé le 28 juin 1919 dans la galerie des Glaces du château de Versailles."),
        Question(9322, "Qui a été le président de la conférence de paix à Versailles?", listOf("Lloyd George", "Clemenceau", "Woodrow Wilson", "Orlando"), 1, "Histoire", Difficulty.HARD, explanation = "Georges Clemenceau, président du Conseil français, présida la conférence de paix de Versailles en 1919 en tant que doyen des chefs d'État alliés."),
        Question(9323, "Quel était le principal objectif de la Conférence de Versailles?", listOf("Punir l'Allemagne", "Établir une paix durable", "Restaurer l'équilibre européen", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "La Conférence de Versailles visait à établir les conditions de paix après la Première Guerre mondiale, incluant la redéfinition des frontières, les réparations et la création de la Société des Nations."),
        Question(9324, "En quelle année la Société des Nations a-t-elle été établie?", listOf("1918", "1919", "1920", "1921"), 2, "Histoire", Difficulty.HARD, explanation = "La Société des Nations a été créée par le Traité de Versailles en 1919, mais elle a officiellement commencé ses activités le 10 janvier 1920."),
        Question(9325, "Qui a proposé la Société des Nations?", listOf("Lloyd George", "Clemenceau", "Woodrow Wilson", "Lénine"), 2, "Histoire", Difficulty.HARD, explanation = "Woodrow Wilson, président des États-Unis, a proposé la Société des Nations dans ses Quatorze Points en 1918, visant à garantir la paix après la Première Guerre mondiale."),
        Question(9326, "En quelle année la Guerre civile russe a-t-elle commencé?", listOf("1918", "1919", "1920", "1921"), 0, "Histoire", Difficulty.HARD, explanation = "La guerre civile russe a débuté en 1918, après la révolution d'Octobre 1917, lorsque les bolcheviks ont pris le pouvoir et que leurs opposants ont formé l'Armée blanche."),
        Question(9327, "En quelle année la Guerre civile russe s'est-elle terminée?", listOf("1920", "1921", "1922", "1923"), 0, "Histoire", Difficulty.HARD, explanation = "La Guerre civile russe s'est officiellement terminée en 1920 avec la défaite des armées blanches face aux bolcheviks, bien que des combats isolés aient persisté jusqu'en 1922 en Extrême-Orient."),
        Question(9328, "Qui a vaincu dans la Guerre civile russe?", listOf("Les Blancs", "Les Rouges", "Les Verts", "Les Anarchistes"), 1, "Histoire", Difficulty.HARD, explanation = "Les Rouges, dirigés par Lénine et Trotsky, ont vaincu les Blancs et leurs alliés étrangers, établissant l'Union soviétique en 1922."),
        Question(9329, "En quelle année l'URSS a-t-elle été établie?", listOf("1920", "1921", "1922", "1923"), 2, "Histoire", Difficulty.MEDIUM, explanation = "L'Union des républiques socialistes soviétiques a été officiellement créée le 30 décembre 1922 par le traité d'union entre la Russie, l'Ukraine, la Biélorussie et la Transcaucasie."),
        Question(9330, "Qui était le premier chef de l'URSS?", listOf("Staline", "Lénine", "Trotski", "Kamenev"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Lénine a dirigé la révolution bolchevique de 1917 et est devenu le premier chef de l'Union soviétique après sa création en 1922."),
        Question(9331, "En quelle année Lénine est-il mort?", listOf("1921", "1922", "1923", "1924"), 2, "Histoire", Difficulty.HARD, explanation = "Lénine, dirigeant de la révolution russe de 1917 et premier chef de l'URSS, est décédé le 21 janvier 1924. L'année 1923 est incorrecte."),
        Question(9332, "En quelle année Staline a-t-il pris le pouvoir?", listOf("1922", "1924", "1926", "1928"), 2, "Histoire", Difficulty.HARD, explanation = "Après la mort de Lénine en 1924, Staline a consolidé son autorité au sein du Parti communiste et est devenu le dirigeant incontesté de l'Union soviétique en 1926."),
        Question(9333, "Quel était le principal rival de Staline?", listOf("Lénine", "Kamenev", "Trotski", "Boukharine"), 2, "Histoire", Difficulty.HARD, explanation = "Léon Trotski, figure majeure de la Révolution russe, s'opposa à Staline après la mort de Lénine, notamment sur la politique économique et la bureaucratisation du parti."),
        Question(9334, "En quelle année Trotski a-t-il été exilé?", listOf("1926", "1927", "1928", "1929"), 2, "Histoire", Difficulty.HARD, explanation = "Léon Trotski a été exilé par Staline en 1928 après avoir perdu la lutte pour le pouvoir au sein du Parti communiste soviétique, marquant la fin de son influence politique en URSS."),
        Question(9335, "En quelle année la Grande Purge a-t-elle commencé?", listOf("1934", "1935", "1936", "1937"), 3, "Histoire", Difficulty.HARD, explanation = "La Grande Purge, une campagne de répression politique massive en Union soviétique, a été officiellement lancée en 1937 sous le régime de Staline."),
        Question(9336, "En quelle année la Grande Purge s'est-elle terminée?", listOf("1937", "1938", "1939", "1940"), 1, "Histoire", Difficulty.HARD, explanation = "La Grande Purge, une campagne de répression politique menée par Staline en URSS, a culminé en 1938 avant de ralentir. Cette année marque la fin des exécutions de masse et des arrestations les plus intenses."),
        Question(9337, "En quelle année le Procès de Moscou a-t-il eu lieu?", listOf("1935", "1936", "1937", "1938"), 1, "Histoire", Difficulty.HARD, explanation = "Le premier grand procès de Moscou, où d'anciens bolcheviks comme Zinoviev et Kamenev furent jugés pour trahison, s'est tenu en août 1936, marquant le début des Grandes Purges staliniennes."),
        Question(9338, "En quelle année la Nouvelle Politique Économique a-t-elle été établie?", listOf("1919", "1921", "1923", "1925"), 1, "Histoire", Difficulty.HARD, explanation = "La Nouvelle Politique Économique (NEP) fut introduite par Lénine en 1921 pour relancer l'économie soviétique après la guerre civile, en autorisant un certain capitalisme privé."),
        Question(9339, "En quelle année le Plan quinquennal a-t-il commencé?", listOf("1927", "1928", "1929", "1930"), 1, "Histoire", Difficulty.HARD, explanation = "Le premier Plan quinquennal de l'Union soviétique, visant à industrialiser rapidement le pays, a été lancé en 1928 sous Joseph Staline."),
        Question(9340, "Quel était l'objectif principal du Plan quinquennal?", listOf("Industrialiser l'URSS", "Collectiviser l'agriculture", "Augmenter la production", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Les plans quinquennaux soviétiques visaient à industrialiser rapidement le pays, collectiviser l'agriculture et renforcer la puissance militaire, donc tous ces objectifs étaient poursuivis simultanément."),
        Question(9341, "En quelle année Hitler a-t-il écrit Mein Kampf?", listOf("1920", "1923", "1925", "1928"), 2, "Histoire", Difficulty.HARD, explanation = "Hitler a rédigé Mein Kampf en 1924 lors de son emprisonnement après le putsch de la Brasserie, et l'ouvrage a été publié en deux volumes en 1925 et 1926."),
        Question(9342, "En quelle année le Putsch de la Brasserie a-t-il eu lieu?", listOf("1920", "1923", "1925", "1928"), 1, "Histoire", Difficulty.HARD, explanation = "Le Putsch de la Brasserie, tentative de coup d'État menée par Adolf Hitler et le parti nazi à Munich, a échoué le 8-9 novembre 1923."),
        Question(9343, "En quelle année Hitler a-t-il été emprisonné?", listOf("1920", "1923", "1925", "1928"), 1, "Histoire", Difficulty.HARD, explanation = "Hitler fut emprisonné en 1923 après l'échec du putsch de la Brasserie à Munich, un coup d'État raté contre le gouvernement bavarois."),
        Question(9344, "En quelle année la Grande Dépression a-t-elle commencé?", listOf("1927", "1928", "1929", "1930"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le krach boursier de Wall Street en octobre 1929 a déclenché une crise économique mondiale, marquant le début de la Grande Dépression."),
        Question(9345, "Quel événement a déclenché la Grande Dépression?", listOf("Le krach boursier", "L'effondrement de l'économie", "La crise bancaire", "La famine"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le krach boursier de Wall Street en octobre 1929 a provoqué une panique financière et l'effondrement des banques, plongeant l'économie mondiale dans une crise durable."),
        Question(9346, "En quelle année le krach boursier a-t-il eu lieu?", listOf("1927", "1928", "1929", "1930"), 2, "Histoire", Difficulty.HARD, explanation = "Le krach boursier de 1929, qui a débuté le jeudi 24 octobre, est considéré comme le point de départ de la Grande Dépression, la plus grave crise économique du XXe siècle."),
        Question(9347, "En quelle année le NSDAP a-t-il remporté les élections?", listOf("1930", "1932", "1933", "1934"), 2, "Histoire", Difficulty.HARD, explanation = "Le NSDAP d'Adolf Hitler remporta les élections législatives de mars 1933, ce qui lui permit de prendre le pouvoir et d'instaurer la dictature nazie."),
        Question(9348, "En quelle année Hitler a-t-il accédé au pouvoir?", listOf("1932", "1933", "1934", "1935"), 1, "Histoire", Difficulty.EASY, explanation = "Hitler est nommé chancelier le 30 janvier 1933, marquant son accession légale au pouvoir en Allemagne."),
        Question(9349, "Quel événement a consolidé le pouvoir de Hitler?", listOf("Le putsch de la brasserie", "L'incendie du Reichstag", "La Nuit des longs couteaux", "L'Anschluss"), 2, "Histoire", Difficulty.HARD, explanation = "En juin 1934, Hitler ordonna l'élimination des dirigeants SA, dont Ernst Röhm, lors de la Nuit des longs couteaux, ce qui neutralisa une menace interne et gagna le soutien de l'armée allemande."),
        Question(9350, "En quelle année l'incendie du Reichstag a-t-il eu lieu?", listOf("1932", "1933", "1934", "1935"), 1, "Histoire", Difficulty.HARD, explanation = "L'incendie du Reichstag, le bâtiment du Parlement allemand à Berlin, s'est produit le 27 février 1933. Cet événement a été utilisé par Adolf Hitler pour justifier des mesures répressives contre ses opposants politiques."),
        Question(9351, "En quelle année la Nuit des longs couteaux a-t-elle eu lieu?", listOf("1933", "1934", "1935", "1936"), 1, "Histoire", Difficulty.HARD, explanation = "La Nuit des longs couteaux, purge politique menée par Hitler contre les SA, s'est déroulée du 30 juin au 2 juillet 1934."),
        Question(9352, "Qui a été victime de la Nuit des longs couteaux?", listOf("Les communistes", "Les SA", "Les Juifs", "Les opposants"), 1, "Histoire", Difficulty.HARD, explanation = "La Nuit des longs couteaux en 1934 fut une purge ordonnée par Hitler contre les SA, dont il jugeait le chef Ernst Röhm trop menaçant pour son pouvoir."),
        Question(9353, "En quelle année Hindenburg est-il mort?", listOf("1933", "1934", "1935", "1936"), 1, "Histoire", Difficulty.HARD, explanation = "Paul von Hindenburg, président de la République de Weimar, est mort le 2 août 1934, ce qui permit à Adolf Hitler de cumuler les fonctions de chancelier et de président."),
        Question(9354, "En quelle année Hitler s'est-il autoproclamé Führer?", listOf("1933", "1934", "1935", "1936"), 1, "Histoire", Difficulty.HARD, explanation = "En août 1934, à la mort du président Hindenburg, Hitler cumule les fonctions de chancelier et de président, devenant ainsi le Führer et chef suprême de l'Allemagne."),
        Question(9355, "En quelle année le réarmement allemand a-t-il commencé?", listOf("1933", "1934", "1935", "1936"), 2, "Histoire", Difficulty.HARD, explanation = "Le réarmement allemand a officiellement débuté en 1935 avec l'annonce par Hitler de la création de la Luftwaffe et du rétablissement du service militaire obligatoire, violant le traité de Versailles."),
        Question(9356, "En quelle année la Remilitarisation de la Rhénanie a-t-elle eu lieu?", listOf("1934", "1935", "1936", "1937"), 2, "Histoire", Difficulty.HARD, explanation = "La remilitarisation de la Rhénanie en 1936 a violé le traité de Versailles et les accords de Locarno, marquant une escalade majeure des ambitions expansionnistes d'Hitler."),
        Question(9357, "En quelle année la Guerre civile espagnole a-t-elle commencé?", listOf("1934", "1935", "1936", "1937"), 2, "Histoire", Difficulty.HARD, explanation = "La Guerre civile espagnole éclata en juillet 1936 après le soulèvement militaire nationaliste contre le gouvernement républicain."),
        Question(9358, "Qui a déclenché le soulèvement en Espagne?", listOf("Francisco Franco", "Salvador Allende", "Pablo Casals", "Miguel de Unamuno"), 0, "Histoire", Difficulty.HARD, explanation = "Francisco Franco, général nationaliste, a lancé un coup d'État militaire en juillet 1936 contre le gouvernement républicain, déclenchant la guerre civile espagnole."),
        Question(9359, "En quelle année la Guerre civile espagnole s'est-elle terminée?", listOf("1937", "1938", "1939", "1940"), 2, "Histoire", Difficulty.HARD, explanation = "Le conflit s'acheva en 1939 avec la victoire des nationalistes de Franco, qui établirent une dictature jusqu'en 1975."),
        Question(9360, "Qui a soutenu Franco pendant la Guerre civile espagnole?", listOf("L'Allemagne et l'Italie", "L'URSS", "La France et la Grande-Bretagne", "Les États-Unis"), 0, "Histoire", Difficulty.HARD, explanation = "Pendant la Guerre civile espagnole (1936-1939), l'Allemagne nazie et l'Italie fasciste ont soutenu militairement le camp nationaliste de Franco, notamment via la légion Condor et des troupes italiennes."),
        Question(9361, "Qui a soutenu les Républicains espagnols?", listOf("L'Allemagne et l'Italie", "L'URSS", "La France et la Grande-Bretagne", "Les États-Unis"), 1, "Histoire", Difficulty.HARD, explanation = "L'URSS a fourni des armes et des conseillers militaires aux Républicains espagnols pendant la guerre civile, tandis que les puissances fascistes soutenaient les nationalistes de Franco."),
        Question(9362, "En quelle année l'Anschluss a-t-elle eu lieu?", listOf("1936", "1937", "1938", "1939"), 2, "Histoire", Difficulty.HARD, explanation = "L'Anschluss, l'annexion de l'Autriche par l'Allemagne nazie, a eu lieu en mars 1938, sans résistance militaire significative."),
        Question(9363, "Quel était l'objectif de l'Anschluss?", listOf("Annexer l'Autriche", "Annexer la Tchécoslovaquie", "Annexer la Pologne", "Annexer la France"), 0, "Histoire", Difficulty.MEDIUM, explanation = "L'Anschluss était l'annexion de l'Autriche par l'Allemagne nazie en 1938, violant le traité de Versailles et réalisant l'objectif d'Hitler d'unir tous les germanophones sous un seul Reich."),
        Question(9364, "En quelle année la Crise des Sudètes a-t-elle eu lieu?", listOf("1936", "1937", "1938", "1939"), 2, "Histoire", Difficulty.HARD, explanation = "La crise des Sudètes, déclenchée par les revendications allemandes sur cette région tchécoslovaque, a culminé en 1938 avec les accords de Munich qui cèdent le territoire à l'Allemagne nazie."),
        Question(9365, "Quel accord a permis à Hitler d'annexer les Sudètes?", listOf("Accord de Munich", "Accord de Versailles", "Accord de Locarno", "Accord de Brest-Litovsk"), 0, "Histoire", Difficulty.HARD, explanation = "Signé en septembre 1938 entre l'Allemagne, la France, le Royaume-Uni et l'Italie, l'Accord de Munich a cédé les Sudètes à Hitler sans consulter la Tchécoslovaquie."),
        Question(9366, "En quelle année l'accord de Munich a-t-il été signé?", listOf("1937", "1938", "1939", "1940"), 1, "Histoire", Difficulty.HARD, explanation = "L'accord de Munich, signé le 30 septembre 1938, permit à l'Allemagne nazie d'annexer les Sudètes, région tchécoslovaque, sans déclencher de guerre, dans une tentative de politique d'apaisement."),
        Question(9367, "Qui a signé l'Accord de Munich?", listOf("Daladier, Chamberlain et Hitler", "Mussolini et Hitler", "Daladier et Chamberlain", "Roosevelt et Churchill"), 0, "Histoire", Difficulty.HARD, explanation = "L'Accord de Munich de 1938, qui cédait les Sudètes à l'Allemagne nazie, fut signé par le Premier ministre britannique Neville Chamberlain, le président du Conseil français Édouard Daladier et le chancelier allemand Adolf Hitler."),
        Question(9368, "En quelle année Hitler a-t-il annexé le reste de la Tchécoslovaquie?", listOf("1938", "1939", "1940", "1941"), 1, "Histoire", Difficulty.HARD, explanation = "Hitler ordonna l'invasion du reste de la Tchécoslovaquie en mars 1939, violant les accords de Munich de 1938. Cette annexion créa le protectorat de Bohême-Moravie."),
        Question(9369, "En quelle année le Pacte Molotov-Ribbentrop a-t-il été signé?", listOf("1937", "1938", "1939", "1940"), 2, "Histoire", Difficulty.HARD, explanation = "Le Pacte Molotov-Ribbentrop, un traité de non-agression entre l'Allemagne nazie et l'URSS, a été signé le 23 août 1939, peu avant le déclenchement de la Seconde Guerre mondiale."),
        Question(9370, "Quel était l'objectif du Pacte Molotov-Ribbentrop?", listOf("Forme une alliance contre les Alliés", "Non-agression mutuelle", "Partager la Pologne", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Signé en 1939 entre l'URSS et l'Allemagne nazie, ce pacte de non-agression incluait un protocole secret divisant l'Europe de l'Est en zones d'influence."),
        Question(9371, "En quelle année la Seconde Guerre mondiale a-t-elle commencé?", listOf("1938", "1939", "1940", "1941"), 1, "Histoire", Difficulty.EASY, explanation = "L'invasion de la Pologne par l'Allemagne nazie le 1er septembre 1939 est généralement considérée comme le déclencheur du conflit mondial."),
        Question(9372, "En quelle année Hitler a-t-il envahi la Pologne?", listOf("1938", "1939", "1940", "1941"), 1, "Histoire", Difficulty.EASY, explanation = "L'invasion de la Pologne par l'Allemagne nazie le 1er septembre 1939 déclencha la Seconde Guerre mondiale, après l'échec des ultimatums diplomatiques."),
        Question(9373, "En quelle année la Bataille de France a-t-elle eu lieu?", listOf("1939", "1940", "1941", "1942"), 1, "Histoire", Difficulty.HARD, explanation = "La Bataille de France a eu lieu en 1940, lors de la Seconde Guerre mondiale, opposant les forces allemandes aux armées françaises et alliées."),
        Question(9374, "En quelle année la France a-t-elle capitulé?", listOf("1939", "1940", "1941", "1942"), 1, "Histoire", Difficulty.EASY, explanation = "L'armée française a capitulé face à l'Allemagne nazie le 22 juin 1940, après la défaite lors de la bataille de France. Le maréchal Pétain a signé l'armistice à Rethondes."),
        Question(9375, "Quel événement a marqué la défaite de la France?", listOf("L'armistice avec l'Allemagne", "L'invasion allemande", "La Bataille de France", "Le Blitzkrieg"), 0, "Histoire", Difficulty.HARD, explanation = "Le 22 juin 1940, la France signe l'armistice avec l'Allemagne nazie, mettant fin aux combats de la bataille de France et consacrant sa défaite lors de la Seconde Guerre mondiale."),
        Question(9376, "En quelle année la Bataille de Dunkerque a-t-elle eu lieu?", listOf("1939", "1940", "1941", "1942"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Dunkerque s'est déroulée en 1940, lors de la Seconde Guerre mondiale, opposant les forces alliées à l'armée allemande."),
        Question(9377, "En quelle année la Bataille de Grande-Bretagne a-t-elle eu lieu?", listOf("1939", "1940", "1941", "1942"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Grande-Bretagne opposa la Royal Air Force à la Luftwaffe allemande de juillet à octobre 1940, dans le cadre de la Seconde Guerre mondiale."),
        Question(9378, "Qui a commandé la Royal Air Force pendant la Bataille de Grande-Bretagne?", listOf("Hugh Dowding", "Trafford Leigh-Mallory", "Keith Park", "Max Aitken"), 0, "Histoire", Difficulty.HARD, explanation = "Hugh Dowding était le commandant en chef du Fighter Command de la Royal Air Force pendant la Bataille d'Angleterre en 1940, supervisant la défense aérienne contre la Luftwaffe."),
        Question(9379, "En quelle année la Barbarossa a-t-elle commencé?", listOf("1940", "1941", "1942", "1943"), 1, "Histoire", Difficulty.HARD, explanation = "L'opération Barbarossa, l'invasion de l'Union soviétique par l'Allemagne nazie, a débuté le 22 juin 1941, marquant un tournant majeur dans la Seconde Guerre mondiale."),
        Question(9380, "Quel était l'objectif de Barbarossa?", listOf("Envahir l'URSS", "Conquérir la Méditerranée", "Prendre l'Afrique", "Coloniser l'Asie"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Barbarossa était le nom de code de l'invasion de l'Union soviétique par l'Allemagne nazie, lancée le 22 juin 1941."),
        Question(9381, "En quelle année la Bataille de Stalingrad a-t-elle commencé?", listOf("1941", "1942", "1943", "1944"), 1, "Histoire", Difficulty.HARD, explanation = "L'offensive allemande contre Stalingrad a débuté le 23 août 1942, marquant le début de cette bataille majeure de la Seconde Guerre mondiale."),
        Question(9382, "En quelle année la Bataille de Stalingrad s'est-elle terminée?", listOf("1942", "1943", "1944", "1945"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Stalingrad, tournant majeur de la Seconde Guerre mondiale, s'est achevée le 2 février 1943 avec la capitulation de la 6e armée allemande."),
        Question(9383, "Qui a commandé les forces soviétiques à Stalingrad?", listOf("Joukov", "Vatutin", "Chuikov", "Rochossovski"), 2, "Histoire", Difficulty.HARD, explanation = "Vassili Tchouïkov commandait la 62e armée soviétique, chargée de défendre Stalingrad contre l'offensive allemande."),
        Question(9384, "Qui a commandé les forces allemandes à Stalingrad?", listOf("Paulus", "Rommel", "Model", "Guderian"), 0, "Histoire", Difficulty.HARD, explanation = "Friedrich Paulus commandait la 6e armée allemande lors de la bataille de Stalingrad, où il fut encerclé et contraint de capituler en février 1943, marquant un tournant majeur de la Seconde Guerre mondiale."),
        Question(9385, "En quelle année la Bataille de Koursk a-t-elle eu lieu?", listOf("1942", "1943", "1944", "1945"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Koursk, qui s'est déroulée en 1943, est l'une des plus grandes batailles de chars de la Seconde Guerre mondiale, marquant un tournant décisif sur le front de l'Est."),
        Question(9386, "En quelle année l'Allemagne a-t-elle attaqué Pearl Harbor?", listOf("1940", "1941", "1942", "1943"), 0, "Histoire", Difficulty.HARD, explanation = "L'Allemagne n'a pas attaqué Pearl Harbor. C'est le Japon qui a attaqué Pearl Harbor le 7 décembre 1941, et l'Allemagne a ensuite déclaré la guerre aux États-Unis."),
        Question(9387, "Quel était l'objectif de l'attaque de Pearl Harbor?", listOf("Détruire la flotte américaine", "Conquérir les Philippines", "Prendre l'Asie du Sud-Est", "Éliminer les alliés"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Le Japon cherchait à neutraliser la puissance navale américaine dans le Pacifique pour sécuriser ses conquêtes territoriales sans interférence."),
        Question(9388, "En quelle année les États-Unis ont-ils déclaré la guerre au Japon?", listOf("1940", "1941", "1942", "1943"), 1, "Histoire", Difficulty.HARD, explanation = "L'attaque japonaise sur Pearl Harbor le 7 décembre 1941 a poussé les États-Unis à déclarer la guerre au Japon le lendemain, les engageant dans la Seconde Guerre mondiale."),
        Question(9389, "En quelle année la Bataille de Midway a-t-elle eu lieu?", listOf("1941", "1942", "1943", "1944"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Midway s'est déroulée en juin 1942, pendant la Seconde Guerre mondiale, et fut une victoire décisive des États-Unis contre le Japon dans le Pacifique."),
        Question(9390, "Qui a commandé la flotte américaine à Midway?", listOf("Douglas MacArthur", "Chester Nimitz", "William Halsey", "Frank Jack Fletcher"), 2, "Histoire", Difficulty.HARD, explanation = "Bien qu'Halsey fût le commandant désigné, il était hospitalisé pour une infection cutanée. Le contre-amiral Raymond Spruance le remplaça donc à la tête de la flotte américaine lors de la bataille de Midway."),
        Question(9391, "En quelle année la Bataille de Guadalcanal a-t-elle commencé?", listOf("1941", "1942", "1943", "1944"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Guadalcanal, une campagne clé du Pacifique durant la Seconde Guerre mondiale, a débuté le 7 août 1942 avec le débarquement des forces américaines sur l'île."),
        Question(9392, "En quelle année la Bataille de Guadalcanal s'est-elle terminée?", listOf("1941", "1942", "1943", "1944"), 2, "Histoire", Difficulty.HARD, explanation = "La bataille de Guadalcanal, une campagne majeure du Pacifique pendant la Seconde Guerre mondiale, s'est achevée en février 1943 avec la victoire des Alliés sur les forces japonaises."),
        Question(9393, "En quelle année le Jour J a-t-il eu lieu?", listOf("1943", "1944", "1945", "1946"), 1, "Histoire", Difficulty.EASY, explanation = "Le débarquement allié en Normandie, connu sous le nom de Jour J, s'est déroulé le 6 juin 1944 pendant la Seconde Guerre mondiale."),
        Question(9394, "Quel était la date du Jour J?", listOf("5 juin 1944", "6 juin 1944", "7 juin 1944", "8 juin 1944"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le 6 juin 1944 marque le début du débarquement allié en Normandie, une opération militaire majeure de la Seconde Guerre mondiale qui a permis la libération de l'Europe de l'Ouest."),
        Question(9395, "Qui a commandé les forces alliées le Jour J?", listOf("Bernard Montgomery", "Dwight D. Eisenhower", "Omar Bradley", "George Patton"), 1, "Histoire", Difficulty.HARD, explanation = "Dwight D. Eisenhower était le commandant suprême des forces alliées en Europe, ce qui incluait la planification et l'exécution du débarquement du 6 juin 1944 en Normandie."),
        Question(9396, "En quelle année la Libération de Paris a-t-elle eu lieu?", listOf("1943", "1944", "1945", "1946"), 1, "Histoire", Difficulty.HARD, explanation = "La Libération de Paris a eu lieu du 19 au 25 août 1944, marquant la fin de l'occupation allemande de la capitale française pendant la Seconde Guerre mondiale."),
        Question(9397, "Qui a libéré Paris?", listOf("Les Américains", "Les Britanniques", "Les Forces françaises libres", "Les Soviétiques"), 2, "Histoire", Difficulty.HARD, explanation = "Paris a été libérée le 25 août 1944 par la 2e division blindée du général Leclerc, appartenant aux Forces françaises libres, avec le soutien de la Résistance intérieure."),
        Question(9398, "En quelle année la Bataille des Ardennes a-t-elle eu lieu?", listOf("1943", "1944", "1945", "1946"), 2, "Histoire", Difficulty.HARD, explanation = "La Bataille des Ardennes, dernière grande offensive allemande sur le front ouest, a débuté le 16 décembre 1944 et s'est achevée en janvier 1945."),
        Question(9399, "Quel était l'objectif de la Bataille des Ardennes?", listOf("Repousser les Alliés", "Atteindre la mer du Nord", "Détruire Anvers", "Diviser les forces alliées"), 0, "Histoire", Difficulty.HARD, explanation = "Lancée en décembre 1944, cette offensive allemande visait à briser les lignes alliées, reprendre le port d'Anvers et forcer les Alliés à négocier une paix séparée."),
        Question(9400, "En quelle année Hitler s'est-il suicidé?", listOf("1944", "1945", "1946", "1947"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Hitler s'est suicidé le 30 avril 1945 dans son bunker à Berlin, alors que l'Armée rouge était sur le point de prendre la ville, marquant la fin du régime nazi."),
        Question(9401, "En quelle année la Seconde Guerre mondiale en Europe s'est-elle terminée?", listOf("1944", "1945", "1946", "1947"), 1, "Histoire", Difficulty.EASY, explanation = "La Seconde Guerre mondiale en Europe s'est achevée le 8 mai 1945 avec la capitulation sans condition de l'Allemagne nazie."),
        Question(9402, "Qui a signé l'acte de capitulation allemande?", listOf("Goering", "Doenitz", "Jodl", "Speer"), 2, "Histoire", Difficulty.HARD, explanation = "Le général Alfred Jodl, chef d'état-major de la Wehrmacht, a signé la capitulation sans conditions de l'Allemagne nazie le 7 mai 1945 à Reims, mettant fin à la Seconde Guerre mondiale en Europe."),
        Question(9403, "En quelle année le Japon s'est-il rendu?", listOf("1944", "1945", "1946", "1947"), 1, "Histoire", Difficulty.EASY, explanation = "Le Japon a capitulé le 2 septembre 1945, mettant fin à la Seconde Guerre mondiale après les bombardements atomiques d'Hiroshima et Nagasaki."),
        Question(9404, "Quel événement a forcé la reddition du Japon?", listOf("Les bombings atomiques", "La défaite en Chine", "L'invasion soviétique de la Mandchourie", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Les bombardements atomiques d'Hiroshima et Nagasaki, ainsi que l'entrée en guerre de l'Union soviétique, ont contraint le Japon à capituler en août 1945."),
        Question(9405, "En quelle année le Procès de Nuremberg a-t-il commencé?", listOf("1944", "1945", "1946", "1947"), 2, "Histoire", Difficulty.HARD, explanation = "Le procès de Nuremberg s'est ouvert le 20 novembre 1945, mais les principaux dirigeants nazis ont été jugés à partir de 1946, année où les audiences ont véritablement débuté."),
        Question(9406, "Quel était l'objectif du Procès de Nuremberg?", listOf("Juger les criminels de guerre nazis", "Établir le droit international", "Punir les responsables", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Le Procès de Nuremberg visait à juger les criminels de guerre nazis, à établir les principes du droit international et à documenter les atrocités du régime hitlérien."),
        Question(9407, "En quelle année le Procès de Nuremberg s'est-il terminé?", listOf("1945", "1946", "1947", "1948"), 2, "Histoire", Difficulty.HARD, explanation = "Le Procès de Nuremberg, qui jugea les principaux criminels de guerre nazis, s'est ouvert en novembre 1945 et s'est conclu en octobre 1947 avec le verdict final."),
        Question(9408, "En quelle année l'Organisation des Nations unies a-t-elle été créée?", listOf("1944", "1945", "1946", "1947"), 1, "Histoire", Difficulty.EASY, explanation = "L'ONU a été fondée le 24 octobre 1945, après la Seconde Guerre mondiale, pour remplacer la Société des Nations et promouvoir la paix et la coopération internationale."),
        Question(9409, "Quel traité a marqué la fin officielle de la Seconde Guerre mondiale en Europe?", listOf("Traité de Potsdam", "Traité de Versailles", "Traité de San Francisco", "Traité de Paris"), 0, "Histoire", Difficulty.HARD, explanation = "Le Traité de Potsdam, signé en août 1945, a officialisé la fin de la Seconde Guerre mondiale en Europe en fixant les conditions de l'après-guerre et les frontières allemandes."),
        Question(9410, "En quelle année la Conférence de Yalta a-t-elle eu lieu?", listOf("1943", "1944", "1945", "1946"), 2, "Histoire", Difficulty.HARD, explanation = "La conférence de Yalta s'est tenue en février 1945, réunissant Roosevelt, Churchill et Staline pour planifier l'après-guerre et la division de l'Allemagne."),
        Question(9411, "Qui a participé à la Conférence de Yalta?", listOf("Roosevelt, Churchill et Staline", "Eisenhower, Montgomery et Joukov", "Truman, Attlee et Staline", "Roosevelt, Churchill et De Gaulle"), 0, "Histoire", Difficulty.HARD, explanation = "La Conférence de Yalta, en février 1945, réunissait les dirigeants des trois principales puissances alliées : Franklin D. Roosevelt (États-Unis), Winston Churchill (Royaume-Uni) et Joseph Staline (URSS), pour planifier l'après-guerre."),
        Question(9412, "En quelle année la Conférence de Potsdam a-t-elle eu lieu?", listOf("1944", "1945", "1946", "1947"), 1, "Histoire", Difficulty.HARD, explanation = "La Conférence de Potsdam s'est tenue du 17 juillet au 2 août 1945, après la capitulation de l'Allemagne nazie, pour organiser l'après-guerre en Europe."),
        Question(9413, "Qui a participé à la Conférence de Potsdam?", listOf("Roosevelt, Churchill et Staline", "Truman, Attlee et Staline", "Roosevelt, Churchill et De Gaulle", "Eisenhower, Montgomery et Joukov"), 1, "Histoire", Difficulty.HARD, explanation = "La Conférence de Potsdam (juillet-août 1945) réunissait les dirigeants des trois grandes puissances alliées : le président américain Harry Truman, le Premier ministre britannique Clement Attlee (qui succéda à Churchill en cours de conférence) et le dirigeant soviétique Joseph Staline."),
        Question(9414, "En quelle année la Ligne Oder-Neisse a-t-elle été établie?", listOf("1943", "1944", "1945", "1946"), 2, "Histoire", Difficulty.HARD, explanation = "Cette frontière entre l'Allemagne et la Pologne a été fixée en 1945 lors de la conférence de Potsdam, à la fin de la Seconde Guerre mondiale."),
        Question(9415, "Quel était l'objectif de la Ligne Oder-Neisse?", listOf("Frontière entre l'Allemagne et la Pologne", "Frontière entre l'Allemagne et la Tchécoslovaquie", "Frontière entre l'Allemagne et l'URSS", "Ligne de défense allemande"), 0, "Histoire", Difficulty.HARD, explanation = "Établie après la Seconde Guerre mondiale, la ligne Oder-Neisse fixait la frontière entre l'Allemagne et la Pologne, déplaçant le territoire allemand vers l'ouest."),
        Question(9416, "En quelle année la Division de l'Allemagne a-t-elle eu lieu?", listOf("1943", "1944", "1945", "1946"), 2, "Histoire", Difficulty.HARD, explanation = "Après la capitulation de l'Allemagne nazie le 8 mai 1945, les Alliés ont divisé le pays en quatre zones d'occupation, marquant le début de la partition."),
        Question(9417, "En quelle année la Guerre froide a-t-elle commencé?", listOf("1944", "1945", "1946", "1947"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le discours de Fulton de Winston Churchill en 1946, où il évoque le « rideau de fer », est généralement considéré comme le point de départ symbolique de la Guerre froide."),
        Question(9418, "Quel événement a marqué le début de la Guerre froide?", listOf("La fin de la Seconde Guerre mondiale", "Le Discours de Fulton", "La Doctrine Truman", "Le Blocus de Berlin"), 0, "Histoire", Difficulty.HARD, explanation = "La fin de la Seconde Guerre mondiale en 1945 a laissé les États-Unis et l'URSS comme superpuissances rivales, avec des idéologies opposées, déclenchant la Guerre froide."),
        Question(9419, "En quelle année le Discours de Fulton a-t-il été prononcé?", listOf("1945", "1946", "1947", "1948"), 1, "Histoire", Difficulty.HARD, explanation = "Le 5 mars 1946, Winston Churchill prononce son célèbre discours à Fulton, dans le Missouri, où il utilise l'expression « rideau de fer » pour décrire la division de l'Europe."),
        Question(9420, "Qui a prononcé le Discours de Fulton?", listOf("Harry Truman", "Winston Churchill", "Clement Attlee", "Franklin Roosevelt"), 1, "Histoire", Difficulty.HARD, explanation = "Le 5 mars 1946, Winston Churchill prononça le discours de Fulton, dans le Missouri, où il employa l'expression « rideau de fer » pour décrire la division de l'Europe."),
        Question(9421, "En quelle année la Doctrine Truman a-t-elle été annoncée?", listOf("1946", "1947", "1948", "1949"), 1, "Histoire", Difficulty.HARD, explanation = "La Doctrine Truman a été annoncée en 1947 par le président américain Harry S. Truman, établissant une politique d'endiguement du communisme."),
        Question(9422, "Quel était l'objectif de la Doctrine Truman?", listOf("Contenir l'expansion soviétique", "Aider les pays menacés par le communisme", "Établir une alliance avec les États-Unis", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "La doctrine Truman visait à endiguer l'expansion du communisme en soutenant les pays menacés par l'URSS, par une aide économique et militaire, et en affirmant l'engagement américain dans la guerre froide."),
        Question(9423, "En quelle année le Plan Marshall a-t-il été lancé?", listOf("1946", "1947", "1948", "1949"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le Plan Marshall, officiellement nommé Programme de rétablissement européen, a été lancé en 1948 pour aider à la reconstruction de l'Europe après la Seconde Guerre mondiale."),
        Question(9424, "Quel était l'objectif du Plan Marshall?", listOf("Aider la reconstruction de l'Europe", "Contenir l'expansion soviétique", "Établir la stabilité économique", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Le Plan Marshall visait à reconstruire l'Europe après la Seconde Guerre mondiale, à stabiliser les économies pour contrer l'influence soviétique, et à ouvrir les marchés aux produits américains."),
        Question(9425, "Qui a proposé le Plan Marshall?", listOf("Harry Truman", "George Marshall", "Dean Acheson", "John Foster Dulles"), 1, "Histoire", Difficulty.HARD, explanation = "Le Plan Marshall, officiellement nommé Programme de rétablissement européen, a été proposé par le secrétaire d'État américain George Marshall en 1947 pour aider à la reconstruction de l'Europe après la Seconde Guerre mondiale."),
        Question(9426, "En quelle année le Blocus de Berlin a-t-il eu lieu?", listOf("1946", "1947", "1948", "1949"), 2, "Histoire", Difficulty.HARD, explanation = "Le Blocus de Berlin a débuté le 24 juin 1948, lorsque l'Union soviétique a bloqué les accès terrestres à Berlin-Ouest. Cette crise majeure de la Guerre froide a duré près d'un an, jusqu'au 12 mai 1949."),
        Question(9427, "Quel était l'objectif du Blocus de Berlin?", listOf("Forcer l'Occident à quitter Berlin", "Affamer la population", "Établir le contrôle soviétique", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Le blocus de Berlin (1948-1949) visait à forcer les Alliés occidentaux à abandonner Berlin-Ouest, mais il échoua grâce au pont aérien, renforçant la division de l'Allemagne."),
        Question(9428, "En quelle année le Pont aérien de Berlin a-t-il commencé?", listOf("1947", "1948", "1949", "1950"), 1, "Histoire", Difficulty.HARD, explanation = "Le blocus de Berlin par l'Union soviétique a débuté en juin 1948, poussant les Alliés à mettre en place un pont aérien pour ravitailler la ville."),
        Question(9429, "En quelle année le Blocus de Berlin a-t-il pris fin?", listOf("1948", "1949", "1950", "1951"), 1, "Histoire", Difficulty.HARD, explanation = "Le blocus de Berlin, imposé par l'Union soviétique, a pris fin le 12 mai 1949 après que les Alliés occidentaux eurent réussi à ravitailler la ville par un pont aérien pendant près d'un an."),
        Question(9430, "En quelle année l'OTAN a-t-elle été créée?", listOf("1947", "1948", "1949", "1950"), 2, "Histoire", Difficulty.EASY, explanation = "L'OTAN a été créée en 1949 par le traité de Washington pour assurer la défense collective des pays occidentaux face à l'Union soviétique durant la guerre froide."),
        Question(9431, "Quel était l'objectif de l'OTAN?", listOf("Défense collective contre l'URSS", "Établir la stabilité en Europe", "Promouvoir la démocratie", "Tous les trois"), 3, "Histoire", Difficulty.MEDIUM, explanation = "L'OTAN a été créée en 1949 pour assurer la défense collective de ses membres, mais ses objectifs incluent aussi la promotion de la démocratie et la gestion de crises. Les trois réponses proposées (défense collective, valeurs démocratiques, gestion de crises) sont donc correctes."),
        Question(9432, "En quelle année la Corée a-t-elle été divisée?", listOf("1943", "1945", "1948", "1950"), 1, "Histoire", Difficulty.HARD, explanation = "La division de la Corée en deux zones d'occupation, au nord par l'URSS et au sud par les États-Unis, a été décidée à la fin de la Seconde Guerre mondiale en 1945."),
        Question(9433, "En quelle année la Corée du Nord a-t-elle envahi la Corée du Sud?", listOf("1948", "1950", "1952", "1953"), 1, "Histoire", Difficulty.HARD, explanation = "L'invasion nord-coréenne de la Corée du Sud a débuté le 25 juin 1950, déclenchant la guerre de Corée qui a duré jusqu'en 1953."),
        Question(9434, "En quelle année la Guerre de Corée s'est-elle terminée?", listOf("1951", "1952", "1953", "1954"), 2, "Histoire", Difficulty.HARD, explanation = "L'armistice de Panmunjeom, signé le 27 juillet 1953, a mis fin aux combats de la Guerre de Corée, bien qu'aucun traité de paix n'ait été conclu."),
        Question(9435, "Qui a commandé les forces des Nations unies en Corée?", listOf("Eisenhower", "Douglas MacArthur", "Matthew Ridgway", "Van Fleet"), 1, "Histoire", Difficulty.HARD, explanation = "MacArthur fut nommé commandant en chef des forces de l'ONU en 1950, lors de la guerre de Corée, après l'invasion nord-coréenne du Sud."),
        Question(9436, "Quel traité a mis fin à la Guerre de Corée?", listOf("Armistice de Panmunjom", "Traité de Séoul", "Traité de Pusan", "Traité de Kaesong"), 0, "Histoire", Difficulty.HARD, explanation = "Signé en 1953, l'armistice de Panmunjom a établi un cessez-le-feu sans traité de paix officiel, laissant la péninsule coréenne techniquement en guerre."),
        Question(9437, "En quelle année le Pacte de Varsovie a-t-il été créé?", listOf("1953", "1954", "1955", "1956"), 2, "Histoire", Difficulty.HARD, explanation = "Le Pacte de Varsovie fut signé le 14 mai 1955 par l'Union soviétique et sept pays satellites d'Europe de l'Est, en réponse à l'intégration de l'Allemagne de l'Ouest dans l'OTAN."),
        Question(9438, "Quel était l'objectif du Pacte de Varsovie?", listOf("Alliance militaire soviétique", "Contrer l'OTAN", "Établir la domination soviétique", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Le Pacte de Varsovie, créé en 1955, visait à coordonner les défenses des pays du bloc de l'Est contre l'OTAN, à maintenir l'unité communiste et à justifier l'intervention soviétique en cas de menace."),
        Question(9439, "En quelle année la Crise de Suez a-t-elle eu lieu?", listOf("1954", "1955", "1956", "1957"), 2, "Histoire", Difficulty.HARD, explanation = "La Crise de Suez a éclaté en 1956 après la nationalisation du canal de Suez par l'Égypte de Nasser, provoquant une intervention militaire de la France, du Royaume-Uni et d'Israël."),
        Question(9440, "Quel événement a déclenché la Crise de Suez?", listOf("La nationalisation du Canal", "L'invasion d'Égypte", "L'attaque israélienne", "Tous les trois"), 0, "Histoire", Difficulty.HARD, explanation = "En juillet 1956, le président égyptien Gamal Abdel Nasser nationalise la Compagnie du canal de Suez, jusque-là contrôlée par des intérêts franco-britanniques, provoquant une intervention militaire de la France, du Royaume-Uni et d'Israël."),
        Question(9441, "Qui a nationalisé le Canal de Suez?", listOf("Gamal Abdel Nasser", "Anwar Sadate", "Saïd Pacha", "Ismaïl Pacha"), 0, "Histoire", Difficulty.HARD, explanation = "Gamal Abdel Nasser, alors président de l'Égypte, a nationalisé le Canal de Suez le 26 juillet 1956, après le retrait du financement américain et britannique pour le barrage d'Assouan."),
        Question(9442, "En quelle année l'Insurrection de Hongrie a-t-elle eu lieu?", listOf("1955", "1956", "1957", "1958"), 1, "Histoire", Difficulty.HARD, explanation = "L'insurrection de Budapest en 1956 fut un soulèvement populaire contre le régime communiste hongrois et la domination soviétique, écrasé par l'intervention militaire de l'URSS."),
        Question(9443, "Quel était l'objectif de l'Insurrection de Hongrie?", listOf("Renverser le régime communiste", "Obtenir l'indépendance de l'URSS", "Établir un régime démocratique", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "L'Insurrection de Hongrie en 1956 visait à la fois à quitter le Pacte de Varsovie, instaurer un multipartisme et obtenir la neutralité du pays. Ces trois objectifs étaient liés dans la lutte contre le régime communiste soviétique."),
        Question(9444, "En quelle année les soviétiques ont-ils écrasé l'insurrection hongroise?", listOf("1955", "1956", "1957", "1958"), 1, "Histoire", Difficulty.HARD, explanation = "L'insurrection de Budapest, réprimée par l'armée soviétique, a eu lieu du 23 octobre au 10 novembre 1956."),
        Question(9445, "En quelle année Spoutnik a-t-il été lancé?", listOf("1956", "1957", "1958", "1959"), 1, "Histoire", Difficulty.EASY, explanation = "Spoutnik 1, le premier satellite artificiel, a été lancé par l'Union soviétique le 4 octobre 1957, marquant le début de la course spatiale."),
        Question(9446, "Quel était l'objectif de Spoutnik?", listOf("Démontrer la supériorité technologique soviétique", "Lancer un satellite orbital", "Établir la domination spatiale", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "Spoutnik 1 a démontré la faisabilité des satellites artificiels, Spoutnik 2 a envoyé un être vivant dans l'espace, et Spoutnik 3 a mené des études scientifiques. Le programme visait donc à la fois la recherche, l'exploration et la démonstration technologique."),
        Question(9447, "En quelle année Gagarine a-t-il été le premier homme dans l'espace?", listOf("1960", "1961", "1962", "1963"), 1, "Histoire", Difficulty.EASY, explanation = "Le 12 avril 1961, Youri Gagarine a effectué un vol orbital à bord de Vostok 1, marquant le premier voyage humain dans l'espace."),
        Question(9448, "En quelle année John Glenn a-t-il orbitée autour de la Terre?", listOf("1960", "1961", "1962", "1963"), 2, "Histoire", Difficulty.HARD, explanation = "John Glenn est devenu le premier Américain à orbiter autour de la Terre le 20 février 1962, à bord de la capsule Friendship 7."),
        Question(9449, "En quelle année la Crise des missiles cubains a-t-elle eu lieu?", listOf("1960", "1961", "1962", "1963"), 2, "Histoire", Difficulty.MEDIUM, explanation = "En octobre 1962, l'URSS a installé des missiles nucléaires à Cuba, provoquant une confrontation directe avec les États-Unis."),
        Question(9450, "Quel était l'objectif de la Crise des missiles cubains?", listOf("Placer des missiles en Floride", "Placer des missiles à Cuba", "Établir la domination américaine", "Contrer les missiles américains"), 1, "Histoire", Difficulty.HARD, explanation = "En 1962, l'URSS a installé secrètement des missiles nucléaires à Cuba, à proximité des États-Unis, pour dissuader une invasion américaine et équilibrer la puissance nucléaire."),
        Question(9451, "Qui était le leader cubain pendant la Crise des missiles?", listOf("Fidel Castro", "Che Guevara", "Camilo Cienfuegos", "Juan Almeida"), 0, "Histoire", Difficulty.EASY, explanation = "Fidel Castro dirigeait Cuba en 1962, lorsque l'URSS y installa des missiles nucléaires, déclenchant la Crise des missiles avec les États-Unis."),
        Question(9452, "En quelle année la Baie des Cochons a-t-elle eu lieu?", listOf("1960", "1961", "1962", "1963"), 1, "Histoire", Difficulty.HARD, explanation = "L'invasion de la Baie des Cochons, une tentative avortée de renverser Fidel Castro, s'est déroulée en avril 1961 sous l'administration Kennedy."),
        Question(9453, "Quel était l'objectif de la Baie des Cochons?", listOf("Renverser Fidel Castro", "Envahir Cuba", "Établir un gouvernement pro-américain", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "L'invasion de la Baie des Cochons en 1961 visait à renverser Fidel Castro, mais elle échoua. Les trois objectifs principaux étaient d'établir une tête de pont, de déclencher un soulèvement populaire et de remplacer le gouvernement cubain."),
        Question(9454, "En quelle année la Révolution culturelle en Chine a-t-elle commencé?", listOf("1964", "1965", "1966", "1967"), 2, "Histoire", Difficulty.HARD, explanation = "Lancée par Mao Zedong en 1966, la Révolution culturelle visait à purger le Parti communiste chinois des éléments bourgeois et à réaffirmer l'idéologie maoïste."),
        Question(9455, "Quel était l'objectif de la Révolution culturelle?", listOf("Purger la Chine des éléments capitalistes", "Établir la suprématie de Mao", "Transformer la société chinoise", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "La Révolution culturelle, lancée par Mao Zedong en 1966, visait à purger les éléments bourgeois du Parti communiste chinois, à renforcer l'idéologie maoïste et à consolider son pouvoir, d'où la réponse \"Tous les trois\"."),
        Question(9456, "En quelle année la Révolution culturelle s'est-elle terminée?", listOf("1968", "1969", "1976", "1978"), 2, "Histoire", Difficulty.HARD, explanation = "La Révolution culturelle, lancée par Mao Zedong en 1966, s'est officiellement achevée avec sa mort en 1976 et l'arrestation de la Bande des quatre."),
        Question(9457, "En quelle année la Guerre du Viêt Nam a-t-elle commencé pour les États-Unis?", listOf("1962", "1964", "1965", "1966"), 2, "Histoire", Difficulty.HARD, explanation = "L'engagement militaire direct des États-Unis au Viêt Nam a commencé en 1965 avec l'opération Rolling Thunder et le déploiement des premiers combattants à Da Nang."),
        Question(9458, "Quel événement a déclenché l'escalade américaine au Viêt Nam?", listOf("L'incident du Golfe du Tonkin", "La chute de Diên Biên Phủ", "L'indépendance du Viêt Nam du Nord", "L'attaque du Viêt Cong"), 0, "Histoire", Difficulty.HARD, explanation = "En août 1964, une prétendue attaque nord-vietnamienne contre un destroyer américain dans le golfe du Tonkin a conduit le Congrès américain à adopter une résolution autorisant une intervention militaire accrue."),
        Question(9459, "En quelle année la Guerre du Viêt Nam s'est-elle terminée?", listOf("1972", "1973", "1974", "1975"), 3, "Histoire", Difficulty.HARD, explanation = "La guerre du Viêt Nam s'est officiellement terminée le 30 avril 1975 avec la chute de Saïgon, marquant la victoire du Nord-Viêt Nam et la réunification du pays sous régime communiste."),
        Question(9460, "Quel événement a marqué la fin de la Guerre du Viêt Nam?", listOf("La chute de Saïgon", "La Paix avec honneur", "Le Traité de Paris", "L'offensive de Tet"), 0, "Histoire", Difficulty.HARD, explanation = "La chute de Saïgon, le 30 avril 1975, a mis fin à la guerre du Viêt Nam lorsque les forces nord-vietnamiennes ont pris le contrôle de la capitale sud-vietnamienne."),
        Question(9461, "En quelle année le Traité de Paris sur le Viêt Nam a-t-il été signé?", listOf("1972", "1973", "1974", "1975"), 1, "Histoire", Difficulty.HARD, explanation = "Le Traité de Paris, officiellement les Accords de paix de Paris, a été signé le 27 janvier 1973, mettant fin à la participation directe des États-Unis à la guerre du Viêt Nam."),
        Question(9462, "En quelle année la Chute de Saïgon a-t-elle eu lieu?", listOf("1973", "1974", "1975", "1976"), 2, "Histoire", Difficulty.HARD, explanation = "La chute de Saïgon le 30 avril 1975 marque la fin de la guerre du Vietnam, avec la prise de la ville par les forces nord-vietnamiennes et la reddition inconditionnelle du Sud-Vietnam."),
        Question(9463, "En quelle année Richard Nixon a-t-il été élu président?", listOf("1966", "1968", "1970", "1972"), 1, "Histoire", Difficulty.HARD, explanation = "Richard Nixon a remporté l'élection présidentielle américaine de 1968 face au démocrate Hubert Humphrey, dans un contexte marqué par la guerre du Vietnam et les tensions sociales."),
        Question(9464, "En quelle année Nixon a-t-il visité la Chine?", listOf("1970", "1971", "1972", "1973"), 2, "Histoire", Difficulty.HARD, explanation = "La visite de Richard Nixon en Chine en février 1972 a mis fin à plus de deux décennies d'isolement diplomatique entre les deux pays."),
        Question(9465, "Quel était l'objectif de la visite de Nixon en Chine?", listOf("Établir des relations diplomatiques", "Contrer l'URSS", "Promouvoir les échanges commerciaux", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "La visite de Nixon en Chine en 1972 visait à normaliser les relations diplomatiques, à ouvrir des échanges économiques et à établir une coopération stratégique contre l'Union soviétique."),
        Question(9466, "En quelle année le Scandale du Watergate a-t-il éclaté?", listOf("1971", "1972", "1973", "1974"), 1, "Histoire", Difficulty.HARD, explanation = "Le scandale du Watergate a éclaté en 1972 après l'arrestation de cinq hommes ayant cambriolé le siège du Parti démocrate, situé dans l'immeuble du Watergate à Washington. Cette affaire a conduit à la démission du président Richard Nixon en 1974."),
        Question(9467, "En quelle année Nixon a-t-il démissionné?", listOf("1972", "1973", "1974", "1975"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Richard Nixon a démissionné de la présidence des États-Unis en 1974, suite au scandale du Watergate, pour éviter une procédure de destitution."),
        Question(9468, "Qui a succédé à Nixon?", listOf("Gerald Ford", "Henry Kissinger", "Alexander Haig", "Barry Goldwater"), 0, "Histoire", Difficulty.HARD, explanation = "Gerald Ford est devenu président après la démission de Richard Nixon en 1974, suite au scandale du Watergate. Il est le seul président américain à n'avoir jamais été élu à la vice-présidence ou à la présidence."),
        Question(9469, "En quelle année la Détente entre les superpuissances a-t-elle commencé?", listOf("1968", "1969", "1970", "1971"), 1, "Histoire", Difficulty.HARD, explanation = "La Détente, période d'apaisement des tensions entre les États-Unis et l'Union soviétique, a débuté en 1969 avec l'arrivée au pouvoir de Richard Nixon et sa politique de négociation."),
        Question(9470, "Quel traité a marqué le sommet de la Détente?", listOf("SALT I", "SALT II", "ABM Treaty", "START I"), 2, "Histoire", Difficulty.HARD, explanation = "Le traité ABM (Anti-Ballistic Missile Treaty), signé en 1972 entre les États-Unis et l'URSS, a limité les systèmes de défense antimissile, symbolisant l'apogée de la Détente pendant la Guerre froide."),
        Question(9471, "En quelle année la Nouvelle Politique Économique en URSS a-t-elle commencé?", listOf("1985", "1986", "1987", "1988"), 0, "Histoire", Difficulty.HARD, explanation = "Lancée en 1985 par Mikhaïl Gorbatchev, la Nouvelle Politique Économique (NEP) visait à réformer l'économie soviétique en introduisant des éléments de marché, après des décennies de planification centralisée."),
        Question(9472, "En quelle année Mikhail Gorbatchev a-t-il pris le pouvoir?", listOf("1984", "1985", "1986", "1987"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Mikhail Gorbatchev est devenu secrétaire général du Parti communiste de l'Union soviétique en mars 1985, succédant à Konstantin Tchernenko."),
        Question(9473, "Quel était le nom de la politique de reformes de Gorbatchev?", listOf("Glasnost et Perestroika", "Détente", "Coexistence pacifique", "Ouverture"), 0, "Histoire", Difficulty.HARD, explanation = "Glasnost (transparence) et Perestroika (restructuration) étaient les deux piliers des réformes lancées par Mikhaïl Gorbatchev en URSS dans les années 1980 pour moderniser le système soviétique."),
        Question(9474, "En quelle année le Mur de Berlin est-il tombé?", listOf("1988", "1989", "1990", "1991"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le Mur de Berlin est tombé le 9 novembre 1989, marquant la fin de la division de l'Allemagne et un tournant majeur dans la guerre froide."),
        Question(9475, "Quel événement a marqué la fin de la Guerre froide?", listOf("La chute du Mur de Berlin", "La dissolution de l'URSS", "La réunification de l'Allemagne", "Tous les trois"), 3, "Histoire", Difficulty.HARD, explanation = "La chute du mur de Berlin en 1989, la réunification allemande en 1990 et la dissolution de l'URSS en 1991 sont les trois événements clés qui ont mis fin à la Guerre froide."),
        Question(9476, "En quelle année l'Allemagne a-t-elle été réunifiée?", listOf("1988", "1989", "1990", "1991"), 2, "Histoire", Difficulty.EASY, explanation = "La réunification allemande a eu lieu le 3 octobre 1990, après la chute du mur de Berlin en 1989 et la dissolution de la RDA."),
        Question(9477, "En quelle année la Révolte dans les pays de l'Europe de l'Est a-t-elle commencé?", listOf("1988", "1989", "1990", "1991"), 1, "Histoire", Difficulty.HARD, explanation = "L'année 1989 marque le début des révolutions anticommunistes en Europe de l'Est, avec des manifestations et des changements de régime en Pologne, en Hongrie, en Tchécoslovaquie et en Roumanie."),
        Question(9478, "En quelle année l'URSS s'est-elle officiellement dissoute?", listOf("1989", "1990", "1991", "1992"), 2, "Histoire", Difficulty.EASY, explanation = "L'URSS s'est officiellement dissoute le 26 décembre 1991, à la suite de la déclaration de l'indépendance de plusieurs républiques et de la démission de Mikhaïl Gorbatchev."),
        Question(9479, "Qui a été le dernier leader de l'URSS?", listOf("Léonid Brejnev", "Iouri Andropov", "Konstantin Tchernenko", "Mikhail Gorbatchev"), 3, "Histoire", Difficulty.MEDIUM, explanation = "Mikhail Gorbatchev a été le dernier dirigeant de l'URSS, de 1985 à 1991, et a mis en œuvre les réformes de la perestroïka et de la glasnost qui ont accéléré la dissolution de l'Union soviétique."),
        Question(9480, "En quelle année la Première Guerre du Golfe a-t-elle commencé?", listOf("1989", "1990", "1991", "1992"), 1, "Histoire", Difficulty.HARD, explanation = "L'Irak de Saddam Hussein a envahi le Koweït le 2 août 1990, déclenchant la Première Guerre du Golfe après l'ultimatum de l'ONU."),
        Question(9481, "Quel événement a déclenché la Première Guerre du Golfe?", listOf("L'invasion du Koweït", "Le soutien d'Israël", "L'embargo pétrolier", "L'attaque de l'Iran"), 0, "Histoire", Difficulty.HARD, explanation = "L'invasion du Koweït par l'Irak de Saddam Hussein en août 1990 a conduit à une coalition internationale menée par les États-Unis pour libérer le pays, déclenchant la Première Guerre du Golfe en 1991."),
        Question(9482, "Qui a envahi le Koweït?", listOf("L'Irak", "L'Iran", "L'Arabie Saoudite", "La Syrie"), 0, "Histoire", Difficulty.MEDIUM, explanation = "L'Irak, sous la direction de Saddam Hussein, a envahi le Koweït en août 1990, déclenchant la guerre du Golfe."),
        Question(9483, "En quelle année la Première Guerre du Golfe s'est-elle terminée?", listOf("1990", "1991", "1992", "1993"), 1, "Histoire", Difficulty.HARD, explanation = "La guerre a pris fin en février 1991 après l'opération Tempête du désert menée par une coalition internationale contre l'Irak."),
        Question(9484, "Qui a commandé les forces de la Coalition pendant la Première Guerre du Golfe?", listOf("Norman Schwarzkopf", "Colin Powell", "Tommy Franks", "David Petraeus"), 0, "Histoire", Difficulty.HARD, explanation = "Le général américain Norman Schwarzkopf a dirigé les forces de la Coalition internationale lors de l'opération Tempête du désert en 1991, qui visait à libérer le Koweït de l'invasion irakienne."),
        Question(9485, "En quelle année la Seconde Intifada a-t-elle commencé?", listOf("1998", "1999", "2000", "2001"), 2, "Histoire", Difficulty.HARD, explanation = "La Seconde Intifada, un soulèvement palestinien contre l'occupation israélienne, a débuté en septembre 2000 après la visite d'Ariel Sharon sur l'esplanade des Mosquées à Jérusalem."),
        Question(9486, "En quelle année les attentats du 11 septembre ont-ils eu lieu?", listOf("1999", "2000", "2001", "2002"), 2, "Histoire", Difficulty.EASY, explanation = "Les attentats du 11 septembre 2001 ont été perpétrés par le réseau terroriste Al-Qaïda contre les États-Unis, ciblant les tours jumelles du World Trade Center et le Pentagone."),
        Question(9487, "Qui était responsable des attentats du 11 septembre?", listOf("Al-Qaïda", "Oussama ben Laden", "Taliban", "Mujahidines"), 0, "Histoire", Difficulty.EASY, explanation = "Al-Qaïda, dirigée par Oussama ben Laden, a revendiqué les attentats du 11 septembre 2001 contre les États-Unis, perpétrés par 19 pirates de l'air liés au réseau."),
        Question(9488, "En quelle année la Deuxième Guerre du Golfe a-t-elle commencé?", listOf("2001", "2002", "2003", "2004"), 2, "Histoire", Difficulty.EASY, explanation = "L'invasion de l'Irak par une coalition menée par les États-Unis a débuté le 20 mars 2003, marquant le début officiel de la Deuxième Guerre du Golfe."),
        Question(9489, "Quel était le prétexte de la Deuxième Guerre du Golfe?", listOf("Les armes de destruction massive", "Le soutien du terrorisme", "L'invasion de l'Iran", "La crise du Koweït"), 0, "Histoire", Difficulty.HARD, explanation = "Les États-Unis et leurs alliés ont justifié l'invasion de l'Irak en 2003 en accusant Saddam Hussein de posséder des armes de destruction massive, une menace jamais confirmée."),
        Question(9490, "Qui a commandé les forces de la Coalition pendant la Deuxième Guerre du Golfe?", listOf("Norman Schwarzkopf", "Tommy Franks", "David Petraeus", "George Casey"), 1, "Histoire", Difficulty.HARD, explanation = "Le général Tommy Franks commandait le Commandement central des États-Unis, supervisant les opérations militaires américaines et alliées lors de l'invasion de l'Irak en 2003."),
        Question(9491, "En quelle année Saddam Hussein a-t-il été arrêté?", listOf("2002", "2003", "2004", "2005"), 1, "Histoire", Difficulty.HARD, explanation = "Saddam Hussein a été capturé par les forces américaines le 13 décembre 2003 lors de l'opération Red Dawn, près de Tikrit, en Irak."),
        Question(9492, "En quelle année Saddam Hussein a-t-il été exécuté?", listOf("2004", "2005", "2006", "2007"), 2, "Histoire", Difficulty.HARD, explanation = "Saddam Hussein, ancien président irakien, a été exécuté par pendaison le 30 décembre 2006 après avoir été condamné pour crimes contre l'humanité liés au massacre de 148 chiites à Dujail en 1982."),
        Question(9493, "En quelle année la Chute du Mur de Berlin a-t-elle été officialisée?", listOf("1989", "1990", "1991", "1992"), 0, "Histoire", Difficulty.HARD, explanation = "Le mur de Berlin est tombé le 9 novembre 1989, marquant la fin de la division de l'Allemagne et un tournant dans la guerre froide."),
        Question(9494, "En quelle année la Constitution de la Troisième République a-t-elle été établie?", listOf("1870", "1871", "1875", "1876"), 2, "Histoire", Difficulty.HARD, explanation = "Les lois constitutionnelles de 1875 ont mis en place la Troisième République, qui a duré jusqu'en 1940. Cette constitution a été adoptée après la chute du Second Empire et la défaite de 1870."),
        Question(9495, "Quel pharaon a établi le Nouvel Empire égyptien?", listOf("Amenhotep Ier", "Thoutmosis Ier", "Ahmosis", "Karnak"), 2, "Histoire", Difficulty.HARD, explanation = "Ahmosis Ier a chassé les Hyksôs d'Égypte et réunifié le pays, fondant ainsi la XVIIIe dynastie et inaugurant la période du Nouvel Empire."),
        Question(9496, "En quelle année l'Empire des Achéménides a-t-il été fondé?", listOf("700 avant J.C.", "600 avant J.C.", "550 avant J.C.", "500 avant J.C."), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire achéménide a été fondé vers 550 av. J.-C. par Cyrus le Grand après sa révolte contre l'Empire mède."),
        Question(9497, "Qui a fondé l'Empire des Achéménides?", listOf("Cyrus II", "Darius Ier", "Xerxès Ier", "Artaxerxès"), 0, "Histoire", Difficulty.HARD, explanation = "Cyrus II, dit Cyrus le Grand, a unifié les tribus perses et conquis les Mèdes, la Lydie et Babylone pour fonder le premier empire perse au VIe siècle av. J.-C."),
        Question(9498, "En quelle année le Règne de Périclès a-t-il commencé?", listOf("461 avant J.C.", "455 avant J.C.", "450 avant J.C.", "445 avant J.C."), 0, "Histoire", Difficulty.HARD, explanation = "Périclès devient le principal dirigeant d'Athènes en 461 avant J.C., marquant le début de l'âge d'or athénien."),
        Question(9499, "En quelle année Périclès est-il mort?", listOf("430 avant J.C.", "429 avant J.C.", "428 avant J.C.", "427 avant J.C."), 0, "Histoire", Difficulty.HARD, explanation = "Périclès, stratège et homme d'État majeur d'Athènes, est mort en 430 avant J.-C., victime de la peste qui ravageait la ville durant la guerre du Péloponnèse.")
    )
}
